    def set_window_size_preset(self, width, height):
        """ウィンドウサイズのプリセットを設定"""
        self.width_spin.setValue(width)
        self.height_spin.setValue(height)
    
    def apply_display_settings(self, dialog, close_dialog):
        """表示設定を適用"""
        # ウィンドウサイズを変更
        new_width = self.width_spin.value()
        new_height = self.height_spin.value()
        self.resize(new_width, new_height)
        
        # フォントサイズを変更
        new_font_size = self.font_size_slider.value()
        font = self.font()
        font.setPointSize(new_font_size)
        self.setFont(font)
        
        # すべての子ウィジェットにフォントを適用
        self.apply_font_to_children(self, font)
        
        # 設定を保存
        if self.save_settings_check.isChecked():
            self.save_display_settings(new_width, new_height, new_font_size, self.is_dark_mode)
        
        # ステータスバーに通知
        self.statusBar().showMessage(
            get_text('status_display_settings_applied', new_width, new_height, new_font_size),
            3000
        )
        
        if close_dialog:
            dialog.accept()
    
    def apply_font_to_children(self, widget, font):
        """すべての子ウィジェットにフォントを適用"""
        for child in widget.findChildren(QWidget):
            if hasattr(child, 'setFont'):
                # 特定のウィジェットタイプごとにフォントサイズを調整
                if isinstance(child, (QPushButton, QLabel, QLineEdit, QComboBox)):
                    child_font = QFont(font)
                    child.setFont(child_font)
    
    def save_display_settings(self, width, height, font_size, dark_mode=None):
        """表示設定をファイルに保存"""
        settings_path = os.path.join(session_dir, "display_settings.json")
        settings = {
            "window_width": width,
            "window_height": height,
            "font_size": font_size
        }
        
        if dark_mode is not None:
            settings["dark_mode"] = dark_mode
        elif hasattr(self, 'is_dark_mode'):
            settings["dark_mode"] = self.is_dark_mode
            
        try:
            with open(settings_path, 'w', encoding='utf-8') as f:
                json.dump(settings, f, indent=2)
        except Exception as e:
            print(f"表示設定の保存エラー: {e}")
    
    def load_display_settings(self):
        """保存された表示設定を読み込んで適用"""
        settings_path = os.path.join(session_dir, "display_settings.json")
        
        if os.path.exists(settings_path):
            try:
                with open(settings_path, 'r', encoding='utf-8') as f:
                    settings = json.load(f)
                
                # ウィンドウサイズを適用
                if "window_width" in settings and "window_height" in settings:
                    self.resize(settings["window_width"], settings["window_height"])
                
                # フォントサイズを適用
                if "font_size" in settings:
                    font = self.font()
                    font.setPointSize(settings["font_size"])
                    self.setFont(font)
                    self.apply_font_to_children(self, font)
                
                # ダークモード設定を適用
                if "dark_mode" in settings:
                    self.is_dark_mode = settings["dark_mode"]
                    self.apply_dark_mode(self.is_dark_mode)
                    
            except Exception as e:
                print(f"表示設定の読み込みエラー: {e}")

    # ===========================================
    # Databricks連携機能
    # ===========================================

    def _check_databricks_connection_on_startup(self):
        """起動時にDatabricks接続を確認
        注意: Databricksはデフォルト無効。ユーザーが設定画面から有効化した場合のみ接続を試行する。
        """
        try:
            # Databricks連携が有効な場合のみ接続確認
            if self.mlflow_manager.use_databricks:
                print("起動時Databricks接続確認中...")

                # 接続を試みる（タイムアウト付きで実行）
                self.mlflow_manager.is_initialized = False
                success = self.mlflow_manager.initialize(self.mlflow_manager.folder_path, parent_widget=None)

                if self.mlflow_manager._databricks_connected:
                    print("Databricks接続成功")
                else:
                    print("Databricks接続失敗 - ローカルモードで動作")

                # ステータスラベルを更新
                self._update_databricks_status_label()
            else:
                print("Databricks連携: 無効（設定画面から有効化できます）")
        except Exception as e:
            print(f"起動時Databricks接続確認エラー: {e}")

    def _on_databricks_toggle(self, state):
        """Databricks連携のON/OFF切り替え"""
        enabled = state == Qt.Checked

        # MLflowManagerのモードを切り替え
        self.mlflow_manager.set_databricks_mode(enabled)

        # 有効にした場合は接続を試みる
        if enabled:
            self.statusBar().showMessage("Databricks接続を試行中...", 0)
            QApplication.processEvents()

            self.mlflow_manager.is_initialized = False
            success = self.mlflow_manager.initialize(self.mlflow_manager.folder_path, parent_widget=self)

            self.statusBar().clearMessage()

            if not self.mlflow_manager._databricks_connected:
                QMessageBox.warning(
                    self,
                    get_text('dlg_databricks_connection_error'),
                    get_text('msg_databricks_connection_error_env') +
                    "\n\nDatabricksへの接続に失敗しました。\n"
                    "環境変数 DATABRICKS_HOST と DATABRICKS_TOKEN が正しく設定されているか確認してください。"
                )
                self.databricks_checkbox.setChecked(False)
            else:
                QMessageBox.information(
                    self,
                    "Databricks接続",
                    "Databricksに接続しました。\n"
                    "学習結果はローカルとDatabricksの両方に記録されます。"
                )
        else:
            # ローカルモードに戻す
            self.mlflow_manager.is_initialized = False
            self.mlflow_manager.initialize(self.mlflow_manager.folder_path, parent_widget=self)
            self.statusBar().showMessage("Databricks連携を無効化しました。ローカルのみに記録します。", 3000)

        # 状態ラベルを更新
        self._update_databricks_status_label()

    def _update_databricks_status_label(self):
        """Databricks状態ラベルを更新"""
        backend_info = self.mlflow_manager.get_backend_info()

        if backend_info["type"] == "databricks+local":
            self.databricks_status_label.setText(get_text('label_databricks_combined'))
            self.databricks_status_label.setStyleSheet("color: green; font-size: 10px;")
        elif backend_info["type"] == "databricks":
            if backend_info["status"] == get_text('status_disconnected'):
                self.databricks_status_label.setText(get_text('label_databricks_disconnected'))
                self.databricks_status_label.setStyleSheet("color: orange; font-size: 10px;")
            else:
                self.databricks_status_label.setText(f"✓ Databricks: {backend_info['host'][:30]}...")
                self.databricks_status_label.setStyleSheet("color: green; font-size: 10px;")
        else:
            self.databricks_status_label.setText(get_text('label_local_mlflow'))
            self.databricks_status_label.setStyleSheet("color: gray; font-size: 10px;")

    def _open_local_mlflow_ui(self):
        """ローカルMLflow UIを開く"""
        try:
            import subprocess
            import sys
            import socket
            import webbrowser
            from config import mlflow_dir

            # 既にMLflow UIが起動中(ポート5000使用中)なら二重起動せずブラウザを開く
            with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as _s:
                _s.settimeout(0.3)
                already_running = (_s.connect_ex(("127.0.0.1", 5000)) == 0)

            if already_running:
                webbrowser.open('http://127.0.0.1:5000')
                QMessageBox.information(
                    self,
                    get_text('dlg_mlflow_ui'),
                    get_text('msg_mlflow_ui_started')
                )
                return

            # パスの正規化
            # MLflow 3 ではファイルストア(file://)が使用不可のため sqlite バックエンドを使用
            normalized_path = os.path.normpath(mlflow_dir).replace('\\', '/')
            tracking_uri = f"sqlite:///{normalized_path}/mlflow.db"
            if sys.platform.startswith('win'):
                artifact_root = f"file:///{normalized_path}/mlartifacts"
            else:
                artifact_root = f"file://{normalized_path}/mlartifacts"

            # MLflow UIを起動
            if sys.platform.startswith('win'):
                cmd = f'start cmd /k "mlflow ui --backend-store-uri {tracking_uri} --default-artifact-root {artifact_root} --workers 1"'
                subprocess.Popen(cmd, shell=True)
            else:
                cmd = f'mlflow ui --backend-store-uri {tracking_uri} --default-artifact-root {artifact_root}'
                subprocess.Popen(cmd, shell=True)

            # サーバー起動を待ってからブラウザを開く（3秒後）
            QTimer.singleShot(3000, lambda: webbrowser.open('http://127.0.0.1:5000'))

            QMessageBox.information(
                self,
                get_text('dlg_mlflow_ui'),
                get_text('msg_mlflow_ui_started')
            )
        except Exception as e:
            QMessageBox.critical(
                self,
                get_text('dlg_error'),
                get_text('msg_mlflow_ui_failed', str(e))
            )

    def _ensure_databricks_enabled(self):
        """Databricks連携を有効化し、SDK接続を確立する。成功でTrue、失敗/キャンセルでFalse

        初回の転送・学習からでも接続できるよう、MLflow接続の前にまずSDK接続
        （接続テスト相当）を確立してトークンをキャッシュする。OAuthの場合は
        ここでブラウザ認証が走る。
        """
        # 既に有効かつ接続済みなら何もしない
        if self.mlflow_manager.use_databricks and \
                self.mlflow_manager._databricks_connected:
            return True

        # 未有効なら有効化を確認
        if not self.mlflow_manager.use_databricks:
            reply = QMessageBox.question(
                self,
                get_text('dlg_databricks_not_enabled'),
                get_text('msg_databricks_enable_confirm'),
                QMessageBox.Yes | QMessageBox.No,
                QMessageBox.Yes
            )
            if reply != QMessageBox.Yes:
                return False

        # 1. SDK接続を先に確立（OAuthはブラウザ認証→トークンキャッシュ、PATは検証）
        self.statusBar().showMessage(get_text('db_connecting'), 0)
        QApplication.processEvents()
        try:
            ok, message = DatabricksTransferManager().test_connection()
        except Exception as e:
            ok, message = False, str(e)
        self.statusBar().clearMessage()
        if not ok:
            QMessageBox.warning(
                self,
                get_text('dlg_databricks_connection_failed'),
                get_text('db_connect_failed', message))
            return False

        # 2. MLflowモードを有効化（トークンキャッシュ済みなので接続成功する）
        if not self.mlflow_manager.use_databricks:
            # _on_databricks_toggle が MLflow 接続を行う（失敗時はチェックが外れる）
            self.databricks_checkbox.setChecked(True)
            if not self.mlflow_manager.use_databricks:
                return False
        elif not self.mlflow_manager._databricks_connected:
            self.mlflow_manager.is_initialized = False
            self.mlflow_manager.initialize(
                self.mlflow_manager.folder_path, parent_widget=self)
            self._update_databricks_status_label()
        return True

    def _open_databricks_ui(self):
        """Databricks MLflow UIを開く"""
        # Databricksモードが有効か確認（無効なら有効化を提案）
        if not self._ensure_databricks_enabled():
            return

        # 未接続の場合、接続を試みる
        if not self.mlflow_manager._databricks_connected:
            self.mlflow_manager.is_initialized = False
            success = self.mlflow_manager.initialize(self.mlflow_manager.folder_path, parent_widget=self)

            self._update_databricks_status_label()

            if not self.mlflow_manager._databricks_connected:
                QMessageBox.warning(
                    self,
                    get_text('dlg_databricks_connection_failed'),
                    get_text('msg_databricks_connection_failed')
                )
                return

            QMessageBox.information(
                self,
                get_text('dlg_databricks_connection_success'),
                get_text('msg_databricks_connection_success')
            )

        # Databricks UIを開く
        self.mlflow_manager._open_databricks_ui(self)

        self._update_databricks_status_label()

    def _sync_to_databricks(self):
        """ローカルの学習記録をDatabricksに同期"""
        # 二重起動防止
        if hasattr(self, '_sync_worker') and self._sync_worker is not None and self._sync_worker.isRunning():
            QMessageBox.warning(self, get_text('dialog_warning'), get_text('sync_already_running'))
            return

        # Databricksモードが有効か確認（無効なら有効化を提案）
        if not self._ensure_databricks_enabled():
            return

        # 同期状態を取得
        sync_status = self.mlflow_manager.get_sync_status()

        # 孤立Run数を取得（ローカルで削除されたがDatabricksに残っているRun）
        orphaned_count = self.mlflow_manager.get_orphaned_runs_count()

        # 同期オプションダイアログを表示
        dialog = QDialog(self)
        dialog.setWindowTitle(get_text('dlg_databricks_sync_settings'))
        dialog.setMinimumWidth(450)

        layout = QVBoxLayout(dialog)

        # 状態表示
        status_group = QGroupBox(get_text('section_current_status'))
        status_layout = QVBoxLayout()
        status_layout.addWidget(QLabel(get_text('label_local_runs', sync_status['local_runs'])))
        status_layout.addWidget(QLabel(get_text('label_databricks_runs', sync_status['databricks_runs'])))
        status_layout.addWidget(QLabel(get_text('label_unsynced_runs', sync_status['unsynced_runs'])))
        if orphaned_count > 0:
            orphaned_label = QLabel(get_text('label_orphaned_runs', orphaned_count))
            orphaned_label.setStyleSheet("color: orange;")
            status_layout.addWidget(orphaned_label)
        status_group.setLayout(status_layout)
        layout.addWidget(status_group)

        # 同期オプション
        options_group = QGroupBox(get_text('section_sync_options'))
        options_layout = QVBoxLayout()

        # アップロード同期
        upload_check = QCheckBox(get_text('chk_upload_to_databricks'))
        upload_check.setChecked(True)
        upload_check.setToolTip(get_text('tip_upload_runs'))
        options_layout.addWidget(upload_check)

        # 削除同期
        delete_check = QCheckBox(get_text('chk_delete_from_databricks'))
        delete_check.setChecked(False)
        delete_check.setToolTip(get_text('tip_delete_runs'))
        if orphaned_count > 0:
            delete_check.setText(get_text('chk_delete_runs', orphaned_count))
        options_layout.addWidget(delete_check)

        # 警告ラベル
        warning_label = QLabel(get_text('msg_sync_delete_warning'))
        warning_label.setStyleSheet("color: red; font-size: 10px;")
        options_layout.addWidget(warning_label)

        options_group.setLayout(options_layout)
        layout.addWidget(options_group)

        # ボタン
        button_box = QDialogButtonBox(QDialogButtonBox.Ok | QDialogButtonBox.Cancel)
        button_box.accepted.connect(dialog.accept)
        button_box.rejected.connect(dialog.reject)
        layout.addWidget(button_box)

        if dialog.exec_() != QDialog.Accepted:
            return

        # オプションを取得
        do_upload = upload_check.isChecked()
        do_delete = delete_check.isChecked()

        if not do_upload and not do_delete:
            QMessageBox.information(self, get_text('dialog_info'), get_text('msg_no_sync_option'))
            return

        # 削除確認
        if do_delete and orphaned_count > 0:
            confirm = QMessageBox.warning(
                self,
                get_text('dlg_delete_confirm'),
                get_text('msg_delete_runs_confirm', orphaned_count),
                QMessageBox.Yes | QMessageBox.No,
                QMessageBox.No
            )
            if confirm != QMessageBox.Yes:
                return

        # ツールバーに進捗表示
        self.sync_progress_label.setText(get_text('sync_progress', 0, '?'))

        # バックグラウンドスレッドで同期を実行
        from PyQt5.QtCore import QThread, pyqtSignal

        class SyncWorker(QThread):
            progress_updated = pyqtSignal(int, int, str)  # current, total, message
            finished_signal = pyqtSignal(dict)  # result
            error_signal = pyqtSignal(str)  # error message

            def __init__(self, mlflow_manager, do_delete):
                super().__init__()
                self.mlflow_manager = mlflow_manager
                self.do_delete = do_delete
                self._cancelled = False

            def cancel(self):
                self._cancelled = True

            def run(self):
                try:
                    result = self.mlflow_manager.sync_local_to_databricks(
                        parent_widget=None,
                        progress_callback=lambda c, t, m: self.progress_updated.emit(c, t, m),
                        cancel_check=lambda: self._cancelled,
                        delete_orphaned=self.do_delete
                    )
                    self.finished_signal.emit(result)
                except Exception as e:
                    self.error_signal.emit(str(e))

        worker = SyncWorker(self.mlflow_manager, do_delete)

        def on_progress(current, total, message):
            self.sync_progress_label.setText(get_text('sync_progress', current, total))

        def on_finished(result):
            self.sync_progress_label.setText("")
            self._sync_worker = None
            worker.deleteLater()

            if result.get("cancelled"):
                result_message = (
                    f"同期がキャンセルされました。\n\n"
                    f"キャンセル前に同期成功: {result['synced']} 件\n"
                    f"スキップ（既存）: {result['skipped']} 件\n"
                    f"削除: {result.get('deleted', 0)} 件"
                )
                QMessageBox.information(self, get_text('dlg_sync_cancelled'), result_message)
            elif result.get("message"):
                QMessageBox.information(self, get_text('dlg_sync_complete'), result["message"])
            else:
                result_message = (
                    f"同期が完了しました。\n\n"
                    f"同期成功: {result['synced']} 件\n"
                    f"スキップ（既存）: {result['skipped']} 件\n"
                    f"失敗: {result['failed']} 件"
                )
                if result.get('deleted', 0) > 0:
                    result_message += f"\n削除: {result['deleted']} 件"

                if result['errors']:
                    result_message += f"\n\nエラー詳細:\n" + "\n".join(result['errors'][:5])
                    if len(result['errors']) > 5:
                        result_message += f"\n... 他 {len(result['errors']) - 5} 件"

                if result['failed'] > 0:
                    QMessageBox.warning(self, get_text('dlg_sync_complete_with_errors'), result_message)
                else:
                    QMessageBox.information(self, get_text('dlg_sync_complete'), result_message)

            self._update_databricks_status_label()

        def on_error(error_msg):
            self.sync_progress_label.setText("")
            self._sync_worker = None
            worker.deleteLater()
            QMessageBox.critical(
                self,
                "同期エラー",
                f"同期中にエラーが発生しました:\n\n{error_msg}"
            )

        worker.progress_updated.connect(on_progress)
        worker.finished_signal.connect(on_finished)
        worker.error_signal.connect(on_error)

        # workerをインスタンス変数に保持してGC防止
        self._sync_worker = worker
        worker.start()

    def _transfer_to_databricks(self):
        """現在のアノテーションをDatabricksに転送"""
        # Databricksモードが有効か確認（無効なら有効化を提案）
        if not self._ensure_databricks_enabled():
            return

        # アノテーションがあるか確認
        if not self.annotations:
            QMessageBox.information(
                self,
                get_text('dlg_info'),
                get_text('msg_no_annotations_to_transfer')
            )
            return

        # ZIPファイル名を入力
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        default_name = f"annotation_{timestamp}"

        zip_name, ok = QInputDialog.getText(
            self,
            get_text('dlg_zip_filename'),
            get_text('msg_enter_zip_filename_databricks'),
            QLineEdit.Normal,
            default_name
        )

        if not ok or not zip_name.strip():
            return

        zip_name = zip_name.strip()
        if not zip_name.endswith('.zip'):
            zip_name += '.zip'

        # 転送先を確認
        from databricks.config_databricks import DATABRICKS_VOLUMES_PATH

        # Volumesパスの存在確認
        print("[転送] Volumesパスの存在確認中...")
        temp_manager = DatabricksTransferManager()
        path_exists, path_message = temp_manager.check_volumes_path()

        if not path_exists:
            # パスが存在しない場合、作成を試みるか確認
            create_confirm = QMessageBox.question(
                self,
                get_text('dlg_volumes_path_not_exist'),
                get_text('msg_volumes_path_not_exist', DATABRICKS_VOLUMES_PATH, path_message),
                QMessageBox.Ok
            )
            return

        # カスタム転送確認ダイアログ（自動学習・モデル種別・ハイパラ・ノートブック配置付き）
        from databricks import config_databricks as db_config
        db_config.reload()
        cluster_id_cur = db_config.DATABRICKS_CLUSTER_ID
        notebook_path_cur = db_config.DATABRICKS_NOTEBOOK_PATH

        confirm_dialog = QDialog(self)
        confirm_dialog.setWindowTitle(get_text('dlg_transfer_confirm'))
        confirm_layout = QVBoxLayout(confirm_dialog)

        confirm_label = QLabel(get_text('msg_transfer_confirm_databricks', len(self.annotations), zip_name, DATABRICKS_VOLUMES_PATH))
        confirm_label.setWordWrap(True)
        confirm_layout.addWidget(confirm_label)

        auto_train_checkbox = QCheckBox(get_text('chk_auto_train_after_transfer'))
        confirm_layout.addWidget(auto_train_checkbox)

        # 学習設定グループ（自動学習ON時のみ有効）
        train_group = QGroupBox(get_text('db_train_settings'))
        train_form = QFormLayout()

        # コンピュート選択（サーバーレス＝フリープラン対応 / クラスター）
        compute_combo = QComboBox()
        compute_combo.addItem(get_text('db_compute_serverless'), 'serverless')
        compute_combo.addItem(get_text('db_compute_cluster'), 'cluster')
        # クラスターIDが設定済みなら既定でクラスター、無ければサーバーレス
        compute_combo.setCurrentIndex(1 if cluster_id_cur else 0)
        train_form.addRow(get_text('db_field_compute'), compute_combo)

        # サーバーレス環境（アクセラレータ/環境バージョン/GPUベース環境）
        # ノートブックに紐づく環境を上書きし、GPU/CPU不整合を回避する
        accel_combo = QComboBox()
        accel_combo.addItem(get_text('db_accel_cpu'), 'cpu')
        accel_combo.addItem(get_text('db_accel_gpu'), 'gpu')
        accel_label = QLabel(get_text('db_field_accelerator'))
        train_form.addRow(accel_label, accel_combo)

        env_version_edit = QLineEdit("2")
        env_version_edit.setToolTip(get_text('db_tip_env_version'))
        env_version_label = QLabel(get_text('db_field_env_version'))
        train_form.addRow(env_version_label, env_version_edit)

        base_env_edit = QLineEdit()
        base_env_edit.setPlaceholderText(get_text('db_base_env_placeholder'))
        base_env_edit.setToolTip(get_text('db_tip_base_env'))
        base_env_label = QLabel(get_text('db_field_base_env'))
        train_form.addRow(base_env_label, base_env_edit)

        def _on_compute_or_accel_changed():
            is_serverless = compute_combo.currentData() == 'serverless'
            is_gpu = accel_combo.currentData() == 'gpu'
            # サーバーレス時のみ環境指定を表示
            for w in (accel_label, accel_combo,
                      env_version_label, env_version_edit):
                w.setVisible(is_serverless)
            # GPUベース環境名はサーバーレス＋GPU時のみ
            base_env_label.setVisible(is_serverless and is_gpu)
            base_env_edit.setVisible(is_serverless and is_gpu)
        compute_combo.currentIndexChanged.connect(_on_compute_or_accel_changed)
        accel_combo.currentIndexChanged.connect(_on_compute_or_accel_changed)
        _on_compute_or_accel_changed()

        deploy_checkbox = QCheckBox(get_text('db_chk_deploy_notebooks'))
        deploy_checkbox.setChecked(True)
        deploy_checkbox.setToolTip(get_text('db_tip_deploy'))
        train_form.addRow(deploy_checkbox)

        model_combo = QComboBox()
        model_combo.addItem(get_text('db_model_basic'), "basic")
        model_combo.addItem(get_text('db_model_togivad'), "togivad")
        train_form.addRow(get_text('db_field_model_type'), model_combo)

        epochs_spin = QSpinBox()
        epochs_spin.setRange(1, 500)
        epochs_spin.setValue(10)
        train_form.addRow(get_text('db_field_epochs'), epochs_spin)

        batch_spin = QSpinBox()
        batch_spin.setRange(1, 512)
        batch_spin.setValue(32)
        train_form.addRow(get_text('db_field_batch'), batch_spin)

        lr_spin = QDoubleSpinBox()
        lr_spin.setDecimals(5)
        lr_spin.setRange(0.00001, 1.0)
        lr_spin.setSingleStep(0.0001)
        lr_spin.setValue(0.001)
        train_form.addRow(get_text('db_field_lr'), lr_spin)

        vocab_spin = QSpinBox()
        vocab_spin.setRange(8, 1024)
        vocab_spin.setValue(128)
        vocab_row_label = QLabel(get_text('db_field_vocab_k'))
        train_form.addRow(vocab_row_label, vocab_spin)

        # togivad選択時のみ語彙Kを表示、basic時は隠す
        def _on_model_changed():
            is_togivad = model_combo.currentData() == "togivad"
            vocab_spin.setVisible(is_togivad)
            vocab_row_label.setVisible(is_togivad)
        model_combo.currentIndexChanged.connect(_on_model_changed)
        _on_model_changed()

        train_group.setLayout(train_form)
        train_group.setEnabled(False)
        confirm_layout.addWidget(train_group)
        auto_train_checkbox.toggled.connect(train_group.setEnabled)

        button_box = QDialogButtonBox(QDialogButtonBox.Ok | QDialogButtonBox.Cancel)
        button_box.accepted.connect(confirm_dialog.accept)
        button_box.rejected.connect(confirm_dialog.reject)
        confirm_layout.addWidget(button_box)

        if confirm_dialog.exec_() != QDialog.Accepted:
            return

        do_auto_train = auto_train_checkbox.isChecked()
        do_deploy_notebooks = do_auto_train and deploy_checkbox.isChecked()
        use_serverless = compute_combo.currentData() == 'serverless'
        # クラスター実行を選んだのにクラスター未指定なら中止
        if do_auto_train and not use_serverless and not cluster_id_cur:
            QMessageBox.warning(self, get_text('dlg_transfer_confirm'),
                                get_text('tip_auto_train_cluster_required'))
            return
        # サーバーレス環境の指定（GPU/CPU不整合の回避）
        serverless_env_version = env_version_edit.text().strip() if use_serverless else ""
        serverless_base_environment = (
            base_env_edit.text().strip()
            if use_serverless and accel_combo.currentData() == 'gpu' else "")
        train_model_type = model_combo.currentData()
        train_params = {
            "epochs": epochs_spin.value(),
            "batch_size": batch_spin.value(),
            "learning_rate": lr_spin.value(),
        }
        if train_model_type == "togivad":
            train_params["vocab_k"] = vocab_spin.value()
        else:
            train_params["image_column"] = "cam/image_array"

        # 進捗ダイアログを作成
        progress = QProgressDialog(get_text('msg_preparing_transfer'), get_text('btn_cancel'), 0, 100, self)
        progress.setWindowTitle(get_text('dlg_transferring_to_databricks'))
        progress.setWindowModality(Qt.WindowModal)
        progress.setMinimumDuration(0)
        progress.setMinimumWidth(400)
        progress.setValue(0)
        progress.show()

        # キャンセルフラグ
        cancelled = [False]

        def progress_callback(stage, current, total, message):
            QApplication.processEvents()
            if progress.wasCanceled():
                cancelled[0] = True
                return

            # ステージに応じた進捗計算
            # export: 0-20%, zip: 20-60%, upload: 60-100%
            if stage == 'export':
                percent = int((current / max(total, 1)) * 20)
                stage_name = "エクスポート中"
            elif stage == 'zip':
                percent = 20 + int((current / max(total, 1)) * 40)
                stage_name = "ZIP圧縮中"
            elif stage == 'upload':
                percent = 60 + int((current / max(total, 1)) * 40)
                stage_name = "アップロード中"
            else:
                percent = 0
                stage_name = ""

            progress.setValue(percent)
            progress.setLabelText(f"{stage_name}\n{message}")
            QApplication.processEvents()

        def cancel_check():
            QApplication.processEvents()
            return progress.wasCanceled() or cancelled[0]

        # 転送実行
        try:
            print("[転送] DatabricksTransferManager を作成中...")
            # DatabricksTransferManagerを作成
            transfer_manager = DatabricksTransferManager()

            print("[転送] image_mapとvariant_keysを構築中...")
            # image_mapとvariant_keysを構築
            image_map = {}
            variant_keys = {}

            # source_images_mapから構築
            if hasattr(self, 'source_images_map') and self.source_images_map:
                print(f"[転送] source_images_map を使用（バリアント数: {len(self.source_images_map)}）")
                for variant, images_list in self.source_images_map.items():
                    # variant_keysを設定
                    if variant == 'cam':
                        variant_keys[variant] = 'cam/image_array'
                    elif variant == 'cam0':
                        variant_keys[variant] = 'cam0/image_array'
                    elif variant == 'lidar':
                        variant_keys[variant] = 'lidar/image_array'
                    else:
                        variant_keys[variant] = f'{variant}/image_array'

                    # image_mapを構築
                    for idx, img_path in enumerate(images_list):
                        if idx not in image_map:
                            image_map[idx] = {}
                        image_map[idx][variant] = img_path
                print(f"[転送] image_map 構築完了（エントリ数: {len(image_map)}）")
            else:
                # 単一ソースの場合
                if hasattr(self, 'images') and self.images:
                    print(f"[転送] 単一ソースを使用（画像数: {len(self.images)}）")
                    variant_keys['cam'] = 'cam/image_array'
                    for idx, img_path in enumerate(self.images):
                        image_map[idx] = {'cam': img_path}

            # 削除インデックスを取得
            deleted_indexes = getattr(self, 'deleted_indexes', [])
            print(f"[転送] 削除インデックス数: {len(deleted_indexes)}")

            # 差分ベクトルとウェイポイントを取得
            diff_vectors = getattr(self, 'inference_diff_vectors', None)
            waypoint_annotations = getattr(self, 'waypoint_annotations', None)
            print(f"[転送] 差分ベクトル: {'あり' if diff_vectors else 'なし'}")
            print(f"[転送] ウェイポイント: {'あり' if waypoint_annotations else 'なし'}")

            print("[転送] transfer_annotations 呼び出し...")
            # 転送実行
            result = transfer_manager.transfer_annotations(
                annotations=self.annotations,
                inference_results=self.inference_results if hasattr(self, 'inference_results') else None,
                image_map=image_map,
                variant_keys=variant_keys,
                zip_name=zip_name,
                deleted_indexes=deleted_indexes,
                diff_vectors=diff_vectors,
                waypoint_annotations=waypoint_annotations,
                progress_callback=progress_callback,
                cancel_check=cancel_check
            )

            print(f"[転送] transfer_annotations 完了: {result}")
            progress.close()

            if result['success']:
                # サイズをMBに変換
                size_mb = result['zip_size'] / (1024 * 1024)

                if do_auto_train:
                    try:
                        # ノートブックを自動配置（選択時）
                        if do_deploy_notebooks:
                            deploy_res = transfer_manager.deploy_notebooks(notebook_path_cur)
                            if not deploy_res.get('success'):
                                raise RuntimeError(
                                    get_text('db_msg_deploy_failed',
                                             deploy_res.get('error', '')))
                        run_result = transfer_manager.submit_training_workflow(
                            zip_remote_path=result['remote_path'],
                            notebook_base_path=notebook_path_cur,
                            cluster_id=cluster_id_cur,
                            model_type=train_model_type,
                            train_params=train_params,
                            use_serverless=use_serverless,
                            serverless_env_version=serverless_env_version,
                            serverless_base_environment=serverless_base_environment,
                        )
                        # ジョブ監視ダイアログを起動（完了時にモデル取込を案内）
                        self._monitor_databricks_run(
                            run_result['run_id'], run_result['run_url'],
                            train_model_type)
                    except Exception as e:
                        QMessageBox.warning(
                            self,
                            get_text('dlg_transfer_complete'),
                            get_text('msg_auto_train_failed', str(e))
                        )
                else:
                    QMessageBox.information(
                        self,
                        get_text('dlg_transfer_complete'),
                        get_text('msg_transfer_complete_databricks', result['annotation_count'], size_mb, result['remote_path'])
                    )
            else:
                error_msg = result.get('error', get_text('msg_unknown_error'))
                if 'キャンセル' in error_msg or 'cancel' in error_msg.lower():
                    QMessageBox.information(self, get_text('dialog_transfer_cancel'), get_text('msg_transfer_cancelled'))
                else:
                    QMessageBox.critical(
                        self,
                        get_text('dlg_transfer_error'),
                        get_text('msg_transfer_error', error_msg)
                    )

        except Exception as e:
            progress.close()
            QMessageBox.critical(
                self,
                get_text('dlg_transfer_error'),
                get_text('msg_transfer_error', f"{str(e)}\n\n{traceback.format_exc()}")
            )

    def _monitor_databricks_run(self, run_id, run_url, model_type):
        """Databricks学習ジョブの進捗をポーリング表示し、成功時にモデル取込を案内"""
        import webbrowser

        # 非モーダル：開いたままアプリを操作できる。閉じてもジョブはDatabricks側で継続する
        dialog = QDialog(self)
        dialog.setWindowTitle(get_text('db_monitor_title'))
        dialog.setMinimumWidth(500)
        dialog.setModal(False)
        v = QVBoxLayout(dialog)

        status_label = QLabel(get_text('db_monitor_starting'))
        status_label.setWordWrap(True)
        v.addWidget(status_label)

        task_label = QLabel("")
        task_label.setWordWrap(True)
        task_label.setStyleSheet("font-family: monospace; font-size: 11px;")
        v.addWidget(task_label)

        hint_label = QLabel(get_text('db_monitor_hint'))
        hint_label.setWordWrap(True)
        hint_label.setStyleSheet("color: gray; font-size: 11px;")
        v.addWidget(hint_label)

        btn_row = QHBoxLayout()
        open_btn = QPushButton(get_text('db_monitor_open_browser'))
        open_btn.clicked.connect(lambda: webbrowser.open(run_url))
        logs_btn = QPushButton(get_text('db_logs_fetch'))
        logs_btn.clicked.connect(lambda: self._show_databricks_run_logs(run_id))
        close_btn = QPushButton(get_text('btn_close'))
        close_btn.clicked.connect(dialog.close)
        btn_row.addWidget(open_btn)
        btn_row.addWidget(logs_btn)
        btn_row.addStretch()
        btn_row.addWidget(close_btn)
        v.addLayout(btn_row)

        try:
            monitor_manager = DatabricksTransferManager()
        except Exception as e:
            status_label.setText(get_text('db_msg_test_failed', str(e)))
            dialog.show()
            return

        timer = QTimer(dialog)
        state = {"done": False}

        def poll():
            if state["done"]:
                return
            try:
                st = monitor_manager.get_run_status(run_id)
            except Exception as e:
                status_label.setText(get_text('db_monitor_poll_error', str(e)))
                return
            life = st['life_cycle_state']
            res = st.get('result_state') or ""
            status_label.setText(get_text('db_monitor_status', run_id, life, res))
            task_label.setText("\n".join(
                f"  {t['key']}: {t['life_cycle_state']} "
                f"{t.get('result_state') or ''}".rstrip()
                for t in st['tasks']))
            if st['is_terminal']:
                state["done"] = True
                timer.stop()
                if res == "SUCCESS":
                    status_label.setText(get_text('db_monitor_success', run_id))
                    self._offer_model_download(model_type, dialog)
                else:
                    status_label.setText(get_text(
                        'db_monitor_failed', run_id, res,
                        st.get('state_message', '')))

        def on_finished(_result):
            # ダイアログを閉じたらポーリング停止（ジョブ自体はサーバー側で継続）
            timer.stop()
            if hasattr(self, "_db_monitors") and dialog in self._db_monitors:
                self._db_monitors.remove(dialog)

        timer.timeout.connect(poll)
        dialog.finished.connect(on_finished)
        timer.start(5000)
        QTimer.singleShot(300, poll)   # 初回は即時

        # GC防止・参照保持（非モーダルなので即returnしても破棄されないように）
        if not hasattr(self, "_db_monitors"):
            self._db_monitors = []
        self._db_monitors.append(dialog)
        dialog.show()

    def _offer_model_download(self, model_type, parent_dialog):
        """学習済みモデルをVolumesのmodels/からローカルへ取り込む"""
        reply = QMessageBox.question(
            parent_dialog, get_text('db_dl_title'), get_text('db_dl_confirm'),
            QMessageBox.Yes | QMessageBox.No)
        if reply != QMessageBox.Yes:
            return

        try:
            dl_manager = DatabricksTransferManager()
            files = dl_manager.list_remote_files("models")
            candidates = [f for f in files
                          if not f['is_dir']
                          and f['name'].endswith(('.pt', '.pth'))]
            if model_type == "togivad":
                togivad_files = [f for f in candidates
                                 if f['name'].startswith('togivad')]
                if togivad_files:
                    candidates = togivad_files
            if not candidates:
                QMessageBox.information(parent_dialog, get_text('db_dl_title'),
                                        get_text('db_dl_none'))
                return
            # 名前（タイムスタンプ）でソートし最新を選択
            candidates.sort(key=lambda f: f['name'])
            newest = candidates[-1]

            models_dir = os.path.join(APP_DIR_PATH, MODELS_DIR_NAME)
            os.makedirs(models_dir, exist_ok=True)
            local_path = os.path.join(models_dir, newest['name'])

            progress = QProgressDialog(get_text('db_dl_progress'),
                                       get_text('btn_cancel'), 0, 100,
                                       parent_dialog)
            progress.setWindowModality(Qt.WindowModal)
            progress.setMinimumDuration(0)
            progress.setValue(0)
            progress.show()

            def cb(done, total):
                QApplication.processEvents()
                if total:
                    progress.setValue(min(100, int(done / total * 100)))

            dl_manager.download_file(newest['path'], local_path,
                                     progress_callback=cb)
            progress.close()
            QMessageBox.information(parent_dialog, get_text('db_dl_title'),
                                    get_text('db_dl_done', local_path))
        except Exception as e:
            QMessageBox.warning(parent_dialog, get_text('db_dl_title'),
                                get_text('db_dl_failed', str(e)))

    def _sync_databricks_to_local(self):
        """Databricks上のクラウド学習記録（MLflow Run）をすべてローカルへ取得"""
        if not self._ensure_databricks_enabled():
            return

        progress = QProgressDialog(get_text('db_pull_progress'),
                                   get_text('btn_cancel'), 0, 100, self)
        progress.setWindowTitle(get_text('db_menu_pull_records'))
        progress.setWindowModality(Qt.WindowModal)
        progress.setMinimumDuration(0)
        progress.setValue(0)
        progress.show()
        cancelled = [False]

        def pcb(cur, total, msg):
            QApplication.processEvents()
            if progress.wasCanceled():
                cancelled[0] = True
                return
            if total:
                progress.setValue(min(100, int(cur / total * 100)))
            progress.setLabelText(msg)
            QApplication.processEvents()

        def ccheck():
            QApplication.processEvents()
            return progress.wasCanceled() or cancelled[0]

        try:
            res = self.mlflow_manager.sync_databricks_to_local(
                parent_widget=self, progress_callback=pcb, cancel_check=ccheck)
        except Exception as e:
            progress.close()
            QMessageBox.critical(self, get_text('db_menu_pull_records'),
                                 get_text('db_pull_failed', str(e)))
            return
        progress.close()

        if res.get('cancelled'):
            QMessageBox.information(self, get_text('db_menu_pull_records'),
                                    get_text('db_pull_cancelled'))
            return
        if (res.get('synced', 0) == 0 and res.get('skipped', 0) == 0
                and res.get('errors')):
            QMessageBox.warning(self, get_text('db_menu_pull_records'),
                                get_text('db_pull_failed',
                                         "\n".join(res['errors'][:5])))
            return
        msg = res.get('message') or get_text(
            'db_pull_done', res.get('synced', 0),
            res.get('skipped', 0), res.get('failed', 0))
        QMessageBox.information(self, get_text('db_menu_pull_records'), msg)
        try:
            self._update_databricks_status_label()
        except Exception:
            pass

    def _show_databricks_run_logs(self, run_id=None):
        """学習パイプライン（ジョブRun）のログをまとめて取得・表示・保存する

        Args:
            run_id: 対象RunのID。Noneなら最近のRun一覧から選択する。
        """
        if not self._ensure_databricks_enabled():
            return
        try:
            logs_manager = DatabricksTransferManager()
        except Exception as e:
            QMessageBox.warning(self, get_text('db_logs_title'),
                                get_text('db_msg_test_failed', str(e)))
            return

        dialog = QDialog(self)
        dialog.setWindowTitle(get_text('db_logs_title'))
        dialog.setMinimumSize(780, 560)
        v = QVBoxLayout(dialog)

        # Run選択
        top = QHBoxLayout()
        top.addWidget(QLabel(get_text('db_logs_select_run')))
        run_combo = QComboBox()
        top.addWidget(run_combo, 1)
        reload_runs_btn = QPushButton(get_text('db_import_refresh'))
        top.addWidget(reload_runs_btn)
        v.addLayout(top)

        text = QPlainTextEdit()
        text.setReadOnly(True)
        text.setStyleSheet("font-family: monospace; font-size: 11px;")
        text.setLineWrapMode(QPlainTextEdit.NoWrap)
        v.addWidget(text, 1)

        def load_runs():
            run_combo.clear()
            runs = logs_manager.list_recent_runs(limit=30)
            if run_id and not any(r['run_id'] == run_id for r in runs):
                run_combo.addItem(f"Run {run_id}", run_id)
            for r in runs:
                label = (f"{r['run_name']} — {r['life_cycle_state']} "
                         f"{r.get('result_state') or ''} (id={r['run_id']})")
                run_combo.addItem(" ".join(label.split()), r['run_id'])
            if run_id:
                for i in range(run_combo.count()):
                    if run_combo.itemData(i) == run_id:
                        run_combo.setCurrentIndex(i)
                        break

        reload_runs_btn.clicked.connect(load_runs)
        load_runs()

        def fetch_logs():
            rid = run_combo.currentData()
            if rid is None:
                return
            text.setPlainText(get_text('db_logs_fetching'))
            QApplication.processEvents()
            try:
                logs = logs_manager.get_run_logs(int(rid))
                text.setPlainText(logs_manager.format_run_logs(logs))
            except Exception as e:
                text.setPlainText(get_text('db_logs_fetch_failed', str(e)))

        def save_logs():
            content = text.toPlainText()
            if not content.strip():
                return
            rid = run_combo.currentData()
            logs_dir = os.path.join(APP_DIR_PATH, "databricks_logs")
            os.makedirs(logs_dir, exist_ok=True)
            ts = datetime.now().strftime("%Y%m%d_%H%M%S")
            path = os.path.join(logs_dir, f"run_{rid}_{ts}.txt")
            try:
                with open(path, "w", encoding="utf-8") as f:
                    f.write(content)
                QMessageBox.information(dialog, get_text('db_logs_title'),
                                        get_text('db_logs_saved', path))
            except Exception as e:
                QMessageBox.warning(dialog, get_text('db_logs_title'),
                                    get_text('db_logs_save_failed', str(e)))

        def open_browser():
            import webbrowser
            from databricks import config_databricks as db_config
            rid = run_combo.currentData()
            if rid is not None:
                webbrowser.open(
                    f"{db_config.DATABRICKS_HOST.rstrip('/')}/#job/{rid}")

        btn_row = QHBoxLayout()
        fetch_btn = QPushButton(get_text('db_logs_fetch'))
        fetch_btn.clicked.connect(fetch_logs)
        save_btn = QPushButton(get_text('db_logs_save'))
        save_btn.clicked.connect(save_logs)
        open_btn = QPushButton(get_text('db_monitor_open_browser'))
        open_btn.clicked.connect(open_browser)
        close_btn = QPushButton(get_text('btn_close'))
        close_btn.clicked.connect(dialog.accept)
        btn_row.addWidget(fetch_btn)
        btn_row.addWidget(save_btn)
        btn_row.addWidget(open_btn)
        btn_row.addStretch()
        btn_row.addWidget(close_btn)
        v.addLayout(btn_row)

        # 初回自動取得
        if run_combo.count() > 0:
            fetch_logs()

        dialog.exec_()

    def _import_databricks_model(self):
        """DatabricksのVolumes models/ から学習済みモデルを選んでローカルへ取り込む"""
        # Databricksモードが有効か確認（無効なら有効化を提案）
        if not self._ensure_databricks_enabled():
            return

        try:
            mgr = DatabricksTransferManager()
        except Exception as e:
            QMessageBox.warning(self, get_text('db_dl_title'),
                                get_text('db_msg_test_failed', str(e)))
            return

        def list_models():
            try:
                files = mgr.list_remote_files("models")
            except Exception as e:
                QMessageBox.warning(self, get_text('db_dl_title'),
                                    get_text('db_import_list_failed', str(e)))
                return None
            candidates = [f for f in files
                          if not f['is_dir']
                          and f['name'].endswith(('.pt', '.pth'))]
            candidates.sort(key=lambda f: f['name'], reverse=True)  # 新しい順
            return candidates

        candidates = list_models()
        if candidates is None:
            return
        if not candidates:
            QMessageBox.information(self, get_text('db_dl_title'),
                                    get_text('db_dl_none'))
            return

        # 選択ダイアログ
        dialog = QDialog(self)
        dialog.setWindowTitle(get_text('db_import_title'))
        dialog.setMinimumWidth(540)
        v = QVBoxLayout(dialog)
        v.addWidget(QLabel(get_text('db_import_desc')))

        combo = QComboBox()

        def fill_combo(items):
            combo.clear()
            for f in items:
                size_mb = (f.get('size') or 0) / (1024 * 1024)
                combo.addItem(f"{f['name']}  ({size_mb:.1f} MB)", f)
        fill_combo(candidates)
        v.addWidget(combo)

        refresh_btn = QPushButton(get_text('db_import_refresh'))

        def do_refresh():
            items = list_models()
            if items:
                fill_combo(items)
        refresh_btn.clicked.connect(do_refresh)
        v.addWidget(refresh_btn)

        button_box = QDialogButtonBox(QDialogButtonBox.Ok | QDialogButtonBox.Cancel)
        button_box.accepted.connect(dialog.accept)
        button_box.rejected.connect(dialog.reject)
        v.addWidget(button_box)

        if dialog.exec_() != QDialog.Accepted:
            return

        selected = combo.currentData()
        if not selected:
            return

        models_dir = os.path.join(APP_DIR_PATH, MODELS_DIR_NAME)
        os.makedirs(models_dir, exist_ok=True)
        local_path = os.path.join(models_dir, selected['name'])

        # 既存ファイルは上書き確認
        if os.path.exists(local_path):
            if QMessageBox.question(
                    self, get_text('db_dl_title'),
                    get_text('db_import_overwrite', selected['name']),
                    QMessageBox.Yes | QMessageBox.No) != QMessageBox.Yes:
                return

        progress = QProgressDialog(get_text('db_dl_progress'),
                                   get_text('btn_cancel'), 0, 100, self)
        progress.setWindowModality(Qt.WindowModal)
        progress.setMinimumDuration(0)
        progress.setValue(0)
        progress.show()

        def cb(done, total):
            QApplication.processEvents()
            if total:
                progress.setValue(min(100, int(done / total * 100)))

        try:
            mgr.download_file(selected['path'], local_path, progress_callback=cb)
            progress.close()
            QMessageBox.information(self, get_text('db_dl_title'),
                                    get_text('db_dl_done', local_path))
        except Exception as e:
            progress.close()
            QMessageBox.warning(self, get_text('db_dl_title'),
                                get_text('db_dl_failed', str(e)))

    def _show_databricks_settings(self):
        """Databricks設定ダイアログを表示（アプリ内で編集・保存・接続テスト可能）"""
        try:
            from databricks import config_databricks as db_config
            db_config.reload()
            current = db_config.get_all_settings()
            config_available = True
        except ImportError:
            config_available = False
            current = {}

        dialog = QDialog(self)
        dialog.setWindowTitle(get_text('dlg_databricks_settings'))
        dialog.setMinimumWidth(620)
        layout = QVBoxLayout(dialog)

        if not config_available:
            layout.addWidget(QLabel(get_text('msg_config_databricks_not_found')))
            close_button = QPushButton(get_text('btn_close'))
            close_button.clicked.connect(dialog.accept)
            layout.addWidget(close_button)
            dialog.exec_()
            return

        # --- 接続設定（編集可能） ---
        conn_group = QGroupBox(get_text('db_group_connection'))
        form = QFormLayout()

        enabled_check = QCheckBox()
        enabled_check.setChecked(current.get("DATABRICKS_ENABLED") == "true")
        form.addRow(get_text('db_field_enabled'), enabled_check)

        # 認証方式（PAT / OAuth U2M ブラウザ認証）
        auth_combo = QComboBox()
        auth_combo.addItem(get_text('db_auth_pat'), "pat")
        auth_combo.addItem(get_text('db_auth_oauth'), "oauth-u2m")
        auth_combo.setCurrentIndex(
            1 if current.get("DATABRICKS_AUTH_METHOD", "pat") == "oauth-u2m" else 0)
        form.addRow(get_text('db_field_auth_method'), auth_combo)

        host_edit = QLineEdit(current.get("DATABRICKS_HOST", ""))
        host_edit.setPlaceholderText("https://xxx.cloud.databricks.com")
        form.addRow("Host:", host_edit)

        token_edit = QLineEdit(current.get("DATABRICKS_TOKEN", ""))
        token_edit.setEchoMode(QLineEdit.Password)
        token_edit.setPlaceholderText("dapi...")
        token_label = QLabel("Token:")
        form.addRow(token_label, token_edit)

        oauth_hint = QLabel(get_text('db_auth_oauth_hint'))
        oauth_hint.setWordWrap(True)
        oauth_hint.setStyleSheet("color: gray; font-size: 11px;")
        form.addRow("", oauth_hint)

        def _on_auth_changed():
            is_oauth = auth_combo.currentData() == "oauth-u2m"
            token_label.setVisible(not is_oauth)
            token_edit.setVisible(not is_oauth)
            oauth_hint.setVisible(is_oauth)
        auth_combo.currentIndexChanged.connect(_on_auth_changed)
        _on_auth_changed()

        prefix_edit = QLineEdit(current.get("DATABRICKS_EXPERIMENT_PREFIX", ""))
        form.addRow(get_text('db_field_experiment'), prefix_edit)

        volumes_edit = QLineEdit(current.get("DATABRICKS_VOLUMES_PATH", ""))
        form.addRow(get_text('db_field_volumes'), volumes_edit)

        notebook_edit = QLineEdit(current.get("DATABRICKS_NOTEBOOK_PATH", ""))
        form.addRow(get_text('db_field_notebook'), notebook_edit)

        catalog_edit = QLineEdit(current.get("DATABRICKS_CATALOG", ""))
        form.addRow("Catalog:", catalog_edit)
        schema_edit = QLineEdit(current.get("DATABRICKS_SCHEMA", ""))
        form.addRow("Schema:", schema_edit)

        conn_group.setLayout(form)
        layout.addWidget(conn_group)

        # --- クラスター選択（ドロップダウン + 更新） ---
        cluster_group = QGroupBox(get_text('db_group_cluster'))
        cluster_layout = QHBoxLayout()
        cluster_combo = QComboBox()
        cluster_combo.setEditable(True)   # 手入力も許可
        cur_cluster = current.get("DATABRICKS_CLUSTER_ID", "")
        if cur_cluster:
            cluster_combo.addItem(cur_cluster, cur_cluster)
        refresh_cluster_btn = QPushButton(get_text('db_btn_refresh_clusters'))
        cluster_layout.addWidget(cluster_combo, 1)
        cluster_layout.addWidget(refresh_cluster_btn)
        cluster_group.setLayout(cluster_layout)
        layout.addWidget(cluster_group)

        # メッセージ表示
        msg_label = QLabel("")
        msg_label.setWordWrap(True)
        layout.addWidget(msg_label)

        def set_msg(text, color="gray"):
            msg_label.setText(text)
            msg_label.setStyleSheet(f"color: {color};")
            QApplication.processEvents()

        def gather():
            cid = (cluster_combo.currentData()
                   or cluster_combo.currentText() or "").strip()
            return {
                "DATABRICKS_ENABLED": "true" if enabled_check.isChecked() else "false",
                "DATABRICKS_AUTH_METHOD": auth_combo.currentData(),
                "DATABRICKS_HOST": host_edit.text().strip().rstrip('/'),
                "DATABRICKS_TOKEN": token_edit.text().strip(),
                "DATABRICKS_EXPERIMENT_PREFIX": prefix_edit.text().strip(),
                "DATABRICKS_VOLUMES_PATH": volumes_edit.text().strip(),
                "DATABRICKS_NOTEBOOK_PATH": notebook_edit.text().strip(),
                "DATABRICKS_CLUSTER_ID": cid,
                "DATABRICKS_CATALOG": catalog_edit.text().strip(),
                "DATABRICKS_SCHEMA": schema_edit.text().strip(),
            }

        def persist():
            """入力値をストアへ保存し、config/環境変数へ即時反映"""
            db_config.save_settings(gather())

        def do_save():
            persist()
            # MLflow連携モードもチェック状態に同期
            try:
                self.mlflow_manager.set_databricks_mode(enabled_check.isChecked())
                self.databricks_checkbox.blockSignals(True)
                self.databricks_checkbox.setChecked(enabled_check.isChecked())
                self.databricks_checkbox.blockSignals(False)
                self._update_databricks_status_label()
            except Exception:
                pass
            set_msg(get_text('db_msg_saved'), "green")

        def do_test():
            persist()
            set_msg(get_text('db_msg_testing'))
            try:
                mgr = DatabricksTransferManager()
                ok, message = mgr.test_connection()
                set_msg(message, "green" if ok else "red")
            except Exception as e:
                set_msg(get_text('db_msg_test_failed', str(e)), "red")

        def do_refresh_clusters():
            persist()
            set_msg(get_text('db_msg_loading_clusters'))
            try:
                mgr = DatabricksTransferManager()
                clusters = mgr.list_clusters()
                keep = (cluster_combo.currentData()
                        or cluster_combo.currentText() or "").strip()
                cluster_combo.clear()
                for c in clusters:
                    cluster_combo.addItem(
                        f"{c['name']} ({c['state']}) — {c['id']}", c['id'])
                if keep:
                    matched = False
                    for i in range(cluster_combo.count()):
                        if cluster_combo.itemData(i) == keep:
                            cluster_combo.setCurrentIndex(i)
                            matched = True
                            break
                    if not matched:
                        cluster_combo.setEditText(keep)
                set_msg(get_text('db_msg_clusters_loaded', len(clusters)), "green")
            except Exception as e:
                set_msg(get_text('db_msg_clusters_failed', str(e)), "red")

        def do_deploy():
            persist()
            set_msg(get_text('db_msg_deploying'))
            try:
                mgr = DatabricksTransferManager()
                res = mgr.deploy_notebooks(notebook_edit.text().strip())
                if res.get('success'):
                    set_msg(get_text('db_msg_deployed',
                                     len(res['deployed']), res['base_path']), "green")
                else:
                    set_msg(get_text('db_msg_deploy_failed',
                                     res.get('error', '')), "red")
            except Exception as e:
                set_msg(get_text('db_msg_deploy_failed', str(e)), "red")

        refresh_cluster_btn.clicked.connect(do_refresh_clusters)

        # --- 操作ボタン（保存・接続テスト・ノートブック配置） ---
        btn_row = QHBoxLayout()
        save_btn = QPushButton(get_text('db_btn_save'))
        save_btn.clicked.connect(do_save)
        test_btn = QPushButton(get_text('db_btn_test'))
        test_btn.clicked.connect(do_test)
        deploy_btn = QPushButton(get_text('db_btn_deploy'))
        deploy_btn.setToolTip(get_text('db_tip_deploy'))
        deploy_btn.clicked.connect(do_deploy)
        btn_row.addWidget(save_btn)
        btn_row.addWidget(test_btn)
        btn_row.addWidget(deploy_btn)
        layout.addLayout(btn_row)

        # --- 補助ボタン（テンプレ・README・閉じる） ---
        btn_row2 = QHBoxLayout()
        try:
            from databricks.config_databricks import get_env_template
            copy_template_button = QPushButton(get_text('btn_copy_template'))
            copy_template_button.clicked.connect(
                lambda: self._copy_env_template(get_env_template()))
            btn_row2.addWidget(copy_template_button)
        except Exception:
            pass
        open_readme_button = QPushButton(get_text('btn_open_readme'))
        open_readme_button.clicked.connect(self._open_databricks_readme)
        btn_row2.addWidget(open_readme_button)
        close_button = QPushButton(get_text('btn_close'))
        close_button.clicked.connect(dialog.accept)
        btn_row2.addWidget(close_button)
        layout.addLayout(btn_row2)

        dialog.exec_()

    def _copy_env_template(self, template: str):
        """環境変数テンプレートをクリップボードにコピー"""
        from PyQt5.QtWidgets import QApplication
        clipboard = QApplication.clipboard()
        clipboard.setText(template)
        QMessageBox.information(self, get_text('dialog_copy_complete'), get_text('msg_env_copied'))

    def _open_databricks_readme(self):
        """README_DATABRICKS.md を開く"""
        import subprocess
        import sys

        readme_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "README_DATABRICKS.md")

        if not os.path.exists(readme_path):
            QMessageBox.warning(self, get_text('dlg_error'), get_text('msg_readme_not_found', readme_path))
            return

        try:
            if sys.platform.startswith('win'):
                os.startfile(readme_path)
            elif sys.platform.startswith('darwin'):
                subprocess.Popen(['open', readme_path])
            else:
                subprocess.Popen(['xdg-open', readme_path])
        except Exception as e:
            QMessageBox.warning(self, get_text('dlg_error'), get_text('msg_file_open_failed', e))

    # ========================================
    # Google Colab連携メソッド
    # ========================================

    def _is_colab_enabled(self) -> bool:
        """Colab連携が有効かどうかを返す"""
        try:
            from colab.config_colab import COLAB_ENABLED
            return COLAB_ENABLED
        except ImportError:
            return False

    def _on_colab_toggle(self, state):
        """Colabチェックボックスの状態変更"""
        # 現在は環境変数で制御するため、チェックボックスは情報表示のみ
        self._update_colab_status_label()

    def _update_colab_status_label(self):
        """Colabステータスラベルを更新"""
        try:
            from colab.config_colab import get_colab_status
            status = get_colab_status()
            if status['enabled']:
                if status.get('authenticated'):
                    self.colab_status_label.setText(get_text('label_colab_authenticated'))
                    self.colab_status_label.setStyleSheet("color: green;")
                else:
                    self.colab_status_label.setText(get_text('label_colab_not_authenticated'))
                    self.colab_status_label.setStyleSheet("color: orange;")
            else:
                self.colab_status_label.setText(get_text('label_colab_disabled'))
                self.colab_status_label.setStyleSheet("color: gray;")
        except ImportError:
            self.colab_status_label.setText(get_text('label_colab_no_config'))
            self.colab_status_label.setStyleSheet("color: red;")

    def _open_colab_ui(self):
        """Google Colabを開く"""
        import webbrowser
        webbrowser.open("https://colab.research.google.com/")

    def _transfer_to_colab(self):
        """現在のアノテーションをGoogle Driveに転送してColabで学習"""
        # Colabモードが有効か確認
        if not self._is_colab_enabled():
            QMessageBox.warning(
                self,
                get_text('dlg_colab_not_enabled'),
                get_text('msg_colab_not_enabled')
            )
            return

        # アノテーションがあるか確認
        if not self.annotations:
            QMessageBox.information(
                self,
                get_text('dlg_info'),
                get_text('msg_no_annotations_to_transfer')
            )
            return

        # ZIPファイル名を入力
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        default_name = f"annotation_{timestamp}"

        zip_name, ok = QInputDialog.getText(
            self,
            get_text('dlg_zip_filename'),
            get_text('msg_enter_zip_filename_gdrive'),
            QLineEdit.Normal,
            default_name
        )

        if not ok or not zip_name.strip():
            return

        zip_name = zip_name.strip()
        if not zip_name.endswith('.zip'):
            zip_name += '.zip'

        # 転送確認ダイアログ
        try:
            from colab.config_colab import COLAB_DRIVE_FOLDER_NAME
        except ImportError:
            COLAB_DRIVE_FOLDER_NAME = "annotation_data"

        # オプションダイアログを表示
        dialog = QDialog(self)
        dialog.setWindowTitle(get_text('dlg_colab_transfer_settings'))
        dialog.setMinimumWidth(400)

        layout = QVBoxLayout(dialog)

        # 転送内容
        info_group = QGroupBox(get_text('section_transfer_content'))
        info_layout = QVBoxLayout()
        info_layout.addWidget(QLabel(f"アノテーション数: {len(self.annotations)}"))
        info_layout.addWidget(QLabel(f"ファイル名: {zip_name}"))
        info_layout.addWidget(QLabel(f"転送先: Google Drive/{COLAB_DRIVE_FOLDER_NAME}/"))
        info_group.setLayout(info_layout)
        layout.addWidget(info_group)

        # オプション
        options_group = QGroupBox(get_text('section_options'))
        options_layout = QVBoxLayout()

        generate_notebook_check = QCheckBox(get_text('chk_generate_notebook'))
        generate_notebook_check.setChecked(True)
        generate_notebook_check.setToolTip(get_text('tip_generate_notebook'))
        options_layout.addWidget(generate_notebook_check)

        open_colab_check = QCheckBox(get_text('chk_open_colab_after'))
        open_colab_check.setChecked(True)
        open_colab_check.setToolTip(get_text('tip_open_colab'))
        options_layout.addWidget(open_colab_check)

        options_group.setLayout(options_layout)
        layout.addWidget(options_group)

        # 認証に関する注意
        note_label = QLabel(
            "注意: 初回転送時はGoogleアカウントの認証が必要です。\n"
            "ブラウザが開きますので、アカウントを選択して認証してください。"
        )
        note_label.setStyleSheet("color: gray; font-size: 10px;")
        note_label.setWordWrap(True)
        layout.addWidget(note_label)

        # ボタン
        button_box = QDialogButtonBox(QDialogButtonBox.Ok | QDialogButtonBox.Cancel)
        button_box.accepted.connect(dialog.accept)
        button_box.rejected.connect(dialog.reject)
        layout.addWidget(button_box)

        if dialog.exec_() != QDialog.Accepted:
            return

        generate_notebook = generate_notebook_check.isChecked()
        open_colab = open_colab_check.isChecked()

        # 認証確認
        try:
            from utils.colab_transfer import ColabTransferManager

            # 認証中ダイアログを表示
            auth_progress = QProgressDialog(get_text('msg_authenticating_google_drive'), get_text('btn_cancel'), 0, 0, self)
            auth_progress.setWindowTitle(get_text('dlg_authenticating'))
            auth_progress.setWindowModality(Qt.WindowModal)
            auth_progress.setMinimumDuration(0)
            auth_progress.setMinimumWidth(300)
            auth_progress.show()
            QApplication.processEvents()

            # ColabTransferManagerを作成して認証
            transfer_manager = ColabTransferManager()
            success, message = transfer_manager.test_connection()

            auth_progress.close()

            if not success:
                QMessageBox.critical(
                    self,
                    "認証失敗",
                    f"Google Driveへの認証に失敗しました:\n\n{message}"
                )
                return

            # 認証成功 - 転送確認ダイアログを表示
            try:
                from colab.config_colab import COLAB_DRIVE_FOLDER_NAME
            except ImportError:
                COLAB_DRIVE_FOLDER_NAME = "annotation_data"

            confirm_reply = QMessageBox.question(
                self,
                "認証完了 - 転送確認",
                f"Google Driveへの認証が完了しました。\n\n"
                f"以下の内容で転送を開始しますか？\n\n"
                f"  転送先: Google Drive/{COLAB_DRIVE_FOLDER_NAME}/\n"
                f"  ファイル名: {zip_name}\n"
                f"  アノテーション数: {len(self.annotations)}\n"
                f"  Notebook生成: {'あり' if generate_notebook else 'なし'}\n",
                QMessageBox.Yes | QMessageBox.No,
                QMessageBox.Yes
            )

            if confirm_reply != QMessageBox.Yes:
                return

        except ImportError as e:
            QMessageBox.critical(
                self,
                "インポートエラー",
                f"必要なライブラリがインストールされていません:\n\n{str(e)}\n\n"
                "pip install pydrive2 google-auth google-auth-oauthlib pyyaml でインストールしてください。"
            )
            return
        except Exception as e:
            QMessageBox.critical(
                self,
                "認証エラー",
                f"認証中にエラーが発生しました:\n\n{str(e)}"
            )
            return

        # 進捗ダイアログを作成
        progress = QProgressDialog(get_text('msg_preparing_transfer'), get_text('btn_cancel'), 0, 100, self)
        progress.setWindowTitle(get_text('dlg_transferring_to_colab'))
        progress.setWindowModality(Qt.WindowModal)
        progress.setMinimumDuration(0)
        progress.setMinimumWidth(400)
        progress.setValue(0)
        progress.show()

        # キャンセルフラグ
        cancelled = [False]

        # 最後に更新した進捗値を記録（不要な更新を避ける）
        last_percent = [-1]

        def progress_callback(stage, current, total, message):
            # ステージに応じた進捗計算
            if stage == 'export':
                percent = int((current / max(total, 1)) * 15)
                stage_header = "--- ステージ1: エクスポート ---"
                if current == 0:
                    detail = "アノテーションをエクスポート中..."
                else:
                    detail = f"エクスポート完了"
            elif stage == 'zip':
                percent = 15 + int((current / max(total, 1)) * 30)
                stage_header = "--- ステージ2: ZIP圧縮 ---"
                progress_pct = int((current / max(total, 1)) * 100)
                detail = f"ZIP圧縮進捗: {current}/{total} ({progress_pct}%)"
            elif stage == 'upload':
                percent = 45 + int((current / max(total, 1)) * 35)
                stage_header = "--- ステージ3: アップロード ---"
                if current == 0:
                    detail = f"Google Driveにアップロード中...\nファイルサイズ: {total / (1024*1024):.2f} MB"
                else:
                    detail = f"アップロード中: {current // (1024*1024)} MB / {total // (1024*1024)} MB"
            elif stage == 'notebook':
                percent = 80 + int((current / max(total, 1)) * 20)
                stage_header = "--- ステージ4: Notebook生成 ---"
                if current == 0:
                    detail = "Colabノートブックを生成中..."
                else:
                    detail = "ノートブックアップロード完了"
            else:
                percent = 0
                stage_header = ""
                detail = message

            # 進捗値が変わった場合のみGUI更新（パフォーマンス最適化）
            if percent != last_percent[0]:
                last_percent[0] = percent
                progress.setValue(percent)
                progress.setLabelText(f"{stage_header}\n{detail}")
                QApplication.processEvents()

                # キャンセルチェック
                if progress.wasCanceled():
                    cancelled[0] = True

        def cancel_check():
            # cancelled[0]がすでにTrueならprocessEventsをスキップ
            if cancelled[0]:
                return True
            # GUIイベント処理してキャンセル状態を確認
            QApplication.processEvents()
            if progress.wasCanceled():
                cancelled[0] = True
            return cancelled[0]

        # 転送実行
        try:
            # image_mapとvariant_keysを構築（Databricksと同じロジック）
            image_map = {}
            variant_keys = {}

            if hasattr(self, 'source_images_map') and self.source_images_map:
                for variant, images_list in self.source_images_map.items():
                    if variant == 'cam':
                        variant_keys[variant] = 'cam/image_array'
                    elif variant == 'cam0':
                        variant_keys[variant] = 'cam0/image_array'
                    elif variant == 'lidar':
                        variant_keys[variant] = 'lidar/image_array'
                    else:
                        variant_keys[variant] = f'{variant}/image_array'

                    for idx, img_path in enumerate(images_list):
                        if idx not in image_map:
                            image_map[idx] = {}
                        image_map[idx][variant] = img_path
            else:
                if hasattr(self, 'images') and self.images:
                    variant_keys['cam'] = 'cam/image_array'
                    for idx, img_path in enumerate(self.images):
                        image_map[idx] = {'cam': img_path}

            deleted_indexes = getattr(self, 'deleted_indexes', [])
            diff_vectors = getattr(self, 'inference_diff_vectors', None)
            waypoint_annotations = getattr(self, 'waypoint_annotations', None)

            # 転送実行（認証済みのtransfer_managerを使用）
            result = transfer_manager.transfer_annotations(
                annotations=self.annotations,
                inference_results=self.inference_results if hasattr(self, 'inference_results') else None,
                image_map=image_map,
                variant_keys=variant_keys,
                zip_name=zip_name,
                deleted_indexes=deleted_indexes,
                diff_vectors=diff_vectors,
                waypoint_annotations=waypoint_annotations,
                generate_notebook=generate_notebook,
                open_colab=open_colab,
                progress_callback=progress_callback,
                cancel_check=cancel_check
            )

            progress.close()

            if result['success']:
                size_mb = result['zip_size'] / (1024 * 1024)
                message = (
                    f"Google Driveへの転送が完了しました。\n\n"
                    f"アノテーション数: {result['annotation_count']}\n"
                    f"ZIPサイズ: {size_mb:.2f} MB"
                )
                if 'colab_url' in result:
                    message += f"\n\nColab URL:\n{result['colab_url']}"

                QMessageBox.information(self, get_text('dlg_transfer_complete'), message)
                self._update_colab_status_label()
            else:
                error_msg = result.get('error', get_text('msg_unknown_error'))
                if 'キャンセル' in error_msg or 'cancel' in error_msg.lower():
                    QMessageBox.information(self, get_text('dialog_transfer_cancel'), get_text('msg_transfer_cancelled'))
                else:
                    QMessageBox.critical(
                        self,
                        get_text('dlg_transfer_error'),
                        get_text('msg_transfer_error', error_msg)
                    )

        except ImportError as e:
            progress.close()
            QMessageBox.critical(
                self,
                get_text('dlg_import_error'),
                get_text('msg_import_error_colab', str(e))
            )
        except Exception as e:
            progress.close()
            import traceback
            QMessageBox.critical(
                self,
                get_text('dlg_transfer_error'),
                get_text('msg_transfer_error', f"{str(e)}\n\n{traceback.format_exc()}")
            )

    def _download_model_from_colab(self):
        """Colabで学習したモデルをGoogle Driveからダウンロード"""
        # Colabモードが有効か確認
        if not self._is_colab_enabled():
            QMessageBox.warning(
                self,
                get_text('dlg_colab_not_enabled'),
                get_text('msg_colab_not_enabled')
            )
            return

        try:
            from utils.colab_transfer import ColabTransferManager

            # 進捗ダイアログを表示
            progress = QProgressDialog(get_text('msg_connecting_google_drive'), get_text('btn_cancel'), 0, 100, self)
            progress.setWindowTitle(get_text('dlg_fetching_model_list'))
            progress.setWindowModality(Qt.WindowModal)
            progress.setMinimumDuration(0)
            progress.setValue(10)
            progress.show()
            QApplication.processEvents()

            # モデル一覧を取得
            transfer_manager = ColabTransferManager()
            models = transfer_manager.list_models()

            progress.close()

            if not models:
                QMessageBox.information(
                    self,
                    get_text('dlg_no_models'),
                    get_text('msg_google_drive_no_models')
                )
                return

            # モデル選択ダイアログを表示
            dialog = QDialog(self)
            dialog.setWindowTitle(get_text('dlg_download_model'))
            dialog.setMinimumWidth(500)

            layout = QVBoxLayout(dialog)

            # 説明ラベル
            info_label = QLabel(get_text('label_google_drive_models', len(models)))
            layout.addWidget(info_label)

            # モデルリスト
            list_widget = QListWidget()
            for m in models:
                size_mb = m['size'] / (1024 * 1024)
                # 作成日時をフォーマット
                created = m['createdDate'][:10] if m['createdDate'] else get_text('label_unknown_date')
                item_text = f"{m['name']}  ({size_mb:.2f} MB, {created})"
                item = QListWidgetItem(item_text)
                item.setData(Qt.UserRole, m)
                list_widget.addItem(item)

            list_widget.setCurrentRow(0)
            layout.addWidget(list_widget)

            # 保存先
            save_group = QGroupBox(get_text('section_save_location'))
            save_layout = QHBoxLayout()
            save_path_edit = QLineEdit()
            models_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'models')
            save_path_edit.setText(models_dir)
            save_path_edit.setReadOnly(True)
            save_layout.addWidget(save_path_edit)

            browse_button = QPushButton(get_text('btn_browse'))
            def browse_folder():
                folder = QFileDialog.getExistingDirectory(dialog, get_text('dlg_select_save_folder'), models_dir)
                if folder:
                    save_path_edit.setText(folder)
            browse_button.clicked.connect(browse_folder)
            save_layout.addWidget(browse_button)
            save_group.setLayout(save_layout)
            layout.addWidget(save_group)

            # MLflowデータダウンロードオプション
            mlruns_checkbox = QCheckBox(get_text('chk_download_mlruns'))
            mlruns_checkbox.setChecked(True)
            mlruns_checkbox.setToolTip(get_text('tip_merge_mlruns'))
            layout.addWidget(mlruns_checkbox)

            # ボタン
            button_box = QDialogButtonBox(QDialogButtonBox.Ok | QDialogButtonBox.Cancel)
            button_box.accepted.connect(dialog.accept)
            button_box.rejected.connect(dialog.reject)
            layout.addWidget(button_box)

            if dialog.exec_() != QDialog.Accepted:
                return

            # 選択されたモデルを取得
            current_item = list_widget.currentItem()
            if not current_item:
                return

            selected_model = current_item.data(Qt.UserRole)
            save_dir = save_path_edit.text()
            download_mlruns = mlruns_checkbox.isChecked()

            # 同じ名前のモデルが既に存在するかチェック
            local_path = os.path.join(save_dir, selected_model['name'])
            if os.path.exists(local_path):
                local_size = os.path.getsize(local_path)
                remote_size = selected_model['size']

                if local_size == remote_size:
                    # ファイルサイズが一致 → 同一ファイルの可能性が高い
                    reply = QMessageBox.question(
                        self,
                        "同名モデルが存在",
                        f"同じ名前のモデルが既に存在します:\n"
                        f"  {selected_model['name']}\n\n"
                        f"ローカル: {local_size / (1024*1024):.2f} MB\n"
                        f"リモート: {remote_size / (1024*1024):.2f} MB\n\n"
                        f"ファイルサイズが同じため、同一のモデルと思われます。\n"
                        f"ダウンロードをスキップしますか？",
                        QMessageBox.Yes | QMessageBox.No | QMessageBox.Cancel,
                        QMessageBox.Yes
                    )
                    if reply == QMessageBox.Cancel:
                        return
                    elif reply == QMessageBox.Yes:
                        # スキップしてmlrunsのみダウンロード
                        if download_mlruns:
                            progress = QProgressDialog(get_text('msg_downloading_mlflow_data'), get_text('btn_cancel'), 0, 100, self)
                            progress.setWindowTitle(get_text('dlg_downloading'))
                            progress.setWindowModality(Qt.WindowModal)
                            progress.setMinimumDuration(0)
                            progress.setValue(50)
                            progress.show()
                            QApplication.processEvents()

                            try:
                                mlruns_merged = self._download_and_merge_mlruns(transfer_manager, progress)
                            except Exception as e:
                                print(f"[Colab] mlrunsのダウンロードに失敗: {e}")
                            progress.close()

                        QMessageBox.information(
                            self,
                            "スキップ",
                            f"モデルのダウンロードをスキップしました。\n"
                            f"既存のモデルを使用: {local_path}"
                        )
                        return
                    # Noの場合は上書きダウンロードを続行
                else:
                    # ファイルサイズが異なる → 異なるバージョン
                    reply = QMessageBox.question(
                        self,
                        "同名モデルが存在",
                        f"同じ名前のモデルが既に存在しますが、サイズが異なります:\n"
                        f"  {selected_model['name']}\n\n"
                        f"ローカル: {local_size / (1024*1024):.2f} MB\n"
                        f"リモート: {remote_size / (1024*1024):.2f} MB\n\n"
                        f"上書きダウンロードしますか？",
                        QMessageBox.Yes | QMessageBox.No,
                        QMessageBox.No
                    )
                    if reply != QMessageBox.Yes:
                        return

            # ダウンロード実行
            progress = QProgressDialog(get_text('msg_downloading_model'), get_text('btn_cancel'), 0, 100, self)
            progress.setWindowTitle(get_text('dlg_downloading'))
            progress.setWindowModality(Qt.WindowModal)
            progress.setMinimumDuration(0)
            progress.setValue(20)
            progress.show()
            QApplication.processEvents()

            def download_progress(current, total):
                if total > 0:
                    percent = int((current / total) * 80) + 20
                    progress.setValue(percent)
                    progress.setLabelText(get_text('msg_downloading_size', current // (1024*1024), total // (1024*1024)))
                    QApplication.processEvents()

            result_path = transfer_manager.download_file(
                selected_model['id'],
                local_path,
                progress_callback=download_progress
            )

            if result_path:
                # mlrunsをダウンロードしてマージ
                mlruns_merged = False
                if download_mlruns:
                    progress.setLabelText("MLflow実験データをダウンロード中...")
                    progress.setValue(50)
                    QApplication.processEvents()

                    try:
                        mlruns_merged = self._download_and_merge_mlruns(transfer_manager, progress)
                    except Exception as e:
                        print(f"[Colab] mlrunsのダウンロードに失敗: {e}")
                        # mlrunsのエラーは警告のみで続行

                progress.close()

                # ダウンロード成功
                message = f"モデルをダウンロードしました:\n{result_path}"
                if mlruns_merged:
                    message += "\n\nMLflow実験データもマージしました。"
                message += "\n\nこのモデルを読み込みますか？"

                reply = QMessageBox.question(
                    self,
                    "ダウンロード完了",
                    message,
                    QMessageBox.Yes | QMessageBox.No,
                    QMessageBox.Yes
                )

                if reply == QMessageBox.Yes:
                    # モデルを読み込み
                    self._load_downloaded_model(result_path)
            else:
                progress.close()
                QMessageBox.warning(self, get_text('dialog_error'), get_text('msg_model_download_failed'))

        except Exception as e:
            if 'progress' in locals():
                progress.close()
            import traceback
            QMessageBox.critical(
                self,
                "エラー",
                f"モデルのダウンロード中にエラーが発生しました:\n\n{str(e)}\n\n{traceback.format_exc()}"
            )

    def _download_and_merge_mlruns(self, transfer_manager, progress) -> bool:
        """Colabからmlrunsをダウンロードしてローカルにマージ

        Args:
            transfer_manager: ColabTransferManagerインスタンス
            progress: QProgressDialog

        Returns:
            マージ成功した場合True
        """
        import tempfile
        import shutil

        print("[Colab] mlrunsダウンロード開始...")

        # Google Driveからmlrunsをダウンロード
        temp_dir = tempfile.mkdtemp(prefix="mlruns_download_")

        try:
            def mlruns_progress(filename, current, total):
                progress.setLabelText(f"MLflow実験データをダウンロード中: {filename}")
                if total > 0:
                    percent = 50 + int((current / total) * 30)
                    progress.setValue(percent)
                QApplication.processEvents()

            # ローカルのmlrunsパスを取得
            local_mlruns = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'mlruns')

            download_result = transfer_manager.download_mlruns(
                local_dir=temp_dir,
                progress_callback=mlruns_progress,
                compare_with_local=local_mlruns  # ローカルのmlrunsと比較してスキップ
            )

            if not download_result:
                print("[Colab] mlrunsフォルダが見つかりませんでした")
                return False

            remote_mlruns = download_result['path']
            downloaded = download_result['downloaded']
            skipped = download_result['skipped']
            total = download_result['total']

            # スキップ情報を表示
            if skipped > 0:
                if downloaded == 0:
                    print(f"[Colab] 全ファイルが既にダウンロード済みです ({skipped}件)")
                else:
                    print(f"[Colab] ダウンロード: {downloaded}件, スキップ: {skipped}件 (既存)")

            # マージ処理
            progress.setLabelText("MLflow実験データをマージ中...")
            progress.setValue(85)
            QApplication.processEvents()

            merged_count = self._merge_mlruns_folders(remote_mlruns, local_mlruns)

            print(f"[Colab] mlrunsマージ完了: {merged_count}件の実験データをマージ")
            progress.setValue(95)
            QApplication.processEvents()

            return merged_count > 0

        except Exception as e:
            print(f"[Colab] mlrunsマージエラー: {e}")
            import traceback
            traceback.print_exc()
            return False

        finally:
            # 一時ディレクトリをクリーンアップ
            try:
                shutil.rmtree(temp_dir)
            except Exception as e:
                print(f"[Colab] 一時ディレクトリの削除に失敗: {e}")

    def _merge_mlruns_folders(self, source_mlruns: str, dest_mlruns: str) -> int:
        """mlrunsフォルダをマージ

        Args:
            source_mlruns: マージ元のmlrunsパス（Colabからダウンロードしたもの）
            dest_mlruns: マージ先のmlrunsパス（ローカル）

        Returns:
            マージされた実験数
        """
        import shutil

        # ローカルのmlrunsがなければ作成
        os.makedirs(dest_mlruns, exist_ok=True)

        merged_count = 0

        # source_mlruns内の実験フォルダを取得
        if not os.path.exists(source_mlruns):
            return 0

        for item in os.listdir(source_mlruns):
            source_item = os.path.join(source_mlruns, item)

            # .trashフォルダはスキップ
            if item == '.trash':
                continue

            if os.path.isdir(source_item):
                dest_item = os.path.join(dest_mlruns, item)

                if item == 'models':
                    # modelsフォルダは特別扱い（上書きマージ）
                    if os.path.exists(dest_item):
                        # 既存のmodelsフォルダに追加
                        for model_file in os.listdir(source_item):
                            src_model = os.path.join(source_item, model_file)
                            dst_model = os.path.join(dest_item, model_file)
                            if not os.path.exists(dst_model):
                                if os.path.isdir(src_model):
                                    shutil.copytree(src_model, dst_model)
                                else:
                                    shutil.copy2(src_model, dst_model)
                    else:
                        shutil.copytree(source_item, dest_item)
                    continue

                # 実験フォルダ（数字のID）
                if os.path.exists(dest_item):
                    # 既存の実験フォルダがある場合、run単位でマージ
                    for run_id in os.listdir(source_item):
                        src_run = os.path.join(source_item, run_id)
                        dst_run = os.path.join(dest_item, run_id)

                        if os.path.isdir(src_run) and not os.path.exists(dst_run):
                            # 新しいrunをコピー
                            shutil.copytree(src_run, dst_run)
                            print(f"[Colab] run追加: {item}/{run_id}")
                            merged_count += 1
                        elif run_id == 'meta.yaml' and not os.path.exists(dst_run):
                            # meta.yamlをコピー
                            shutil.copy2(src_run, dst_run)
                else:
                    # 新しい実験フォルダをそのままコピー
                    shutil.copytree(source_item, dest_item)
                    # run数をカウント
                    runs = [d for d in os.listdir(dest_item) if os.path.isdir(os.path.join(dest_item, d))]
                    merged_count += len(runs)
                    print(f"[Colab] 実験追加: {item} ({len(runs)} runs)")

        return merged_count

    def _load_downloaded_model(self, model_path: str):
        """ダウンロードしたモデルを読み込む"""
        try:
            import torch

            # モデルをロード
            checkpoint = torch.load(model_path, map_location='cpu')

            # configを取得
            if 'config' in checkpoint:
                config = checkpoint['config']
                model_name = config.get('model_name', config.get('backbone', 'unknown'))
                print(f"[Colab] モデルを読み込みました: {model_name}")

                QMessageBox.information(
                    self,
                    get_text('msg_model_load_complete'),
                    get_text('msg_model_saved_loaded', os.path.basename(model_path), model_name)
                )
            else:
                QMessageBox.information(
                    self,
                    get_text('dlg_model_save_complete'),
                    get_text('msg_model_saved', model_path)
                )

        except Exception as e:
            QMessageBox.warning(
                self,
                "確認エラー",
                f"モデルの確認に失敗しました:\n{str(e)}\n\n"
                "ファイルは保存されています。「モデル読込」ボタンから読み込んでください。"
            )

