    def _get_waypoint_training_config(self, dialog):
        """ウェイポイント学習設定ダイアログから設定値を取得"""

        return {
            'num_waypoints': dialog.waypoint_spin.value(),
            'num_epochs': dialog.epoch_spin.value(),
            'batch_size': dialog.batch_spin.value(),
            'use_augmentation': dialog.aug_check.isChecked(),
            'use_early_stopping': dialog.early_stopping_check.isChecked(),
            'patience': dialog.patience_spin.value() if dialog.early_stopping_check.isChecked() else 0,
            'learning_rate': float(dialog.lr_combo.currentText()),
            'model_name': dialog.model_name_prefix + dialog.model_name_suffix_input.text().strip(),
            'comment': dialog.comment_input.toPlainText().strip()
        }

    def _prepare_waypoint_training_data(self, num_waypoints):
        """ウェイポイント学習データの準備"""

        # データを準備
        image_paths = []
        waypoint_coordinates = []
        skipped_images = []  # スキップされた画像情報

        for idx, waypoints in self.waypoint_annotations.items():
            # インデックスが有効範囲内かチェック
            if isinstance(idx, int) and 0 <= idx < len(self.images):
                # 削除マークされたアノテーションは学習データから除外（actual_indexで判定）
                is_deleted = False
                if hasattr(self, 'deleted_indexes') and idx in self.deleted_indexes:
                    is_deleted = True

                # 削除マークされていない場合のみ学習データに追加
                if not is_deleted and waypoints:
                    img_path = self.images[idx]

                    if len(waypoints) == num_waypoints:
                        # 正しいwaypoint数の場合、学習データに追加
                        image_paths.append(img_path)

                        # 画像サイズを取得して座標を正規化
                        img = Image.open(img_path)
                        img_width, img_height = img.size

                        # ウェイポイント座標を正規化してフラットなリストに変換 [x1, y1, x2, y2, ...]
                        flattened_coords = []
                        for x, y in waypoints:
                            # ピクセル座標を0-1の正規化座標に変換
                            x_norm = float(x) / img_width
                            y_norm = float(y) / img_height
                            flattened_coords.extend([x_norm, y_norm])
                        waypoint_coordinates.append(flattened_coords)
                    else:
                        # waypoint数が一致しない場合、スキップ情報を記録
                        skipped_images.append({
                            'index': idx,
                            'path': img_path,
                            'waypoint_count': len(waypoints),
                            'reason': f'{len(waypoints)}点（必要: {num_waypoints}点）'
                        })

        return {
            'image_paths': image_paths,
            'waypoint_coordinates': waypoint_coordinates,
            'skipped_images': skipped_images
        }

    def _get_location_training_config(self, dialog):
        """学習設定ダイアログから設定値を取得"""

        selected_sources = [v for v, cb in dialog.source_checkboxes.items() if cb.isChecked()]
        is_multi_source = len(selected_sources) > 1
        virtual_type = dialog.virtual_type_combo.currentData() if not is_multi_source else None
        if is_multi_source:
            num_sources = len(selected_sources)
        elif virtual_type:
            num_sources = dialog.virtual_nsrc_spin.value()
        else:
            num_sources = 1

        use_class = dialog.class_output_check.isChecked()
        use_pose = dialog.pose_output_check.isChecked()
        use_grid = dialog.grid_output_check.isChecked()
        from model_catalog import make_output_mode
        output_mode = make_output_mode(use_class=use_class, use_pose=use_pose, use_grid=use_grid)
        needs_pose = use_pose or use_grid   # 自己位置を教師データに使うヘッドがあるか

        return {
            'num_epochs': dialog.epoch_spin.value(),
            'batch_size': dialog.batch_spin.value(),
            'use_augmentation': dialog.aug_check.isChecked(),
            'use_early_stopping': dialog.early_stopping_check.isChecked(),
            'patience': dialog.patience_spin.value() if dialog.early_stopping_check.isChecked() else 0,
            'learning_rate': float(dialog.lr_combo.currentText()),
            'model_name': dialog.model_name_prefix + dialog.model_name_suffix_input.text().strip(),
            'comment': dialog.comment_input.toPlainText().strip(),
            # 入力画像ソース
            'selected_sources': selected_sources,
            'num_sources': num_sources,
            'fusion_method': dialog.fusion_combo.currentData() if is_multi_source else 'concat',
            'virtual_source_type': virtual_type,
            'temporal_interval': dialog.temporal_interval_spin.value() if virtual_type == 'temporal' else 10,
            # 出力（教師データ）
            'output_mode': output_mode,
            'pose_source': dialog.pose_source_combo.currentData() if needs_pose else None,
            'include_heading': dialog.heading_check.isChecked() if use_pose else False,
            'pose_loss_weight': dialog.pose_weight_spin.value() if use_pose else 1.0,
            # 格子分類
            'grid_cell_size': dialog.grid_cell_spin.value() if use_grid else None,
            'grid_loss_weight': dialog.grid_weight_spin.value() if use_grid else 1.0,
            'grid_label_sigma': dialog.grid_sigma_spin.value() if use_grid else 1.0,
            'grid_class_balance': dialog.grid_balance_check.isChecked() if use_grid else True,
            # 解像度（自動運転モデルと同じ: 実画像サイズ × 係数 / ピクセレーション）
            'downscale_factor': dialog.res_slider.value() / 100.0,
            'downscale_mode': 'resize' if dialog.resize_radio.isChecked() else 'pixelate',
        }

    def _location_source_paths_for_index(self, idx, selected_sources, virtual_type=None,
                                         num_sources=1, temporal_interval=10):
        """フレーム idx の位置モデル入力画像パスの組を返す（無ければ None）

        - 複数ソース（実カメラ）: image_groups[idx] から選択ソース順に取得
        - 仮想ソース temporal: 現在＋過去フレーム（先頭でクランプ）を組にする
        - それ以外（単一 / crop / scale）: 1枚（crop/scale はデータセット側で生成）
        """
        groups = getattr(self, 'image_groups', None) or {}
        current_var = getattr(self, 'current_variant', None)

        def _path_for(i, source):
            group = groups.get(i, {})
            if source in group:
                return group[source]
            if source == current_var or not groups:
                return self.images[i] if 0 <= i < len(self.images) else None
            return None

        sources = list(selected_sources) if selected_sources else [current_var]
        if len(sources) > 1:
            paths = [_path_for(idx, s) for s in sources]
            return paths if all(paths) else None

        base = _path_for(idx, sources[0])
        if base is None:
            return None
        if virtual_type == 'temporal' and num_sources > 1:
            paths = [base]
            for k in range(1, num_sources):
                prev = max(0, idx - k * temporal_interval)
                p = _path_for(prev, sources[0])
                paths.append(p if p else base)
            return paths
        return [base]

    def _prepare_location_training_data(self, unique_locations, training_config=None):
        """位置学習データの準備（インデックスベース、複数画像入力・pose ターゲット対応）

        Returns:
            dict: image_paths（代表パス）, grouped_paths（入力画像の組）, location_indices,
                  pose_targets([x, y, theta])、スキップ件数など
        """
        cfg = training_config or {}
        output_mode = cfg.get('output_mode', 'class')
        heads = str(output_mode).split('_')
        use_class = 'class' in heads
        use_pose = 'pose' in heads or 'grid' in heads   # 格子分類も自己位置を教師データに使う
        selected_sources = cfg.get('selected_sources') or [getattr(self, 'current_variant', None)]
        virtual_type = cfg.get('virtual_source_type')
        num_sources = cfg.get('num_sources', 1)
        temporal_interval = cfg.get('temporal_interval', 10)
        pose_source = cfg.get('pose_source')
        deleted = set(getattr(self, 'deleted_indexes', []) or [])

        # 位置ラベルのマッピングを作成（実際の位置値をインデックスに変換）
        location_to_index = {loc: i for i, loc in enumerate(unique_locations)}

        # 対象フレーム: クラス分類ありなら位置アノテーション済み、pose のみなら自己位置のあるフレーム
        if use_class:
            candidate_indexes = sorted(k for k in self.location_annotations.keys() if isinstance(k, int))
        else:
            candidate_indexes = list(self.pose_manager.known_indexes())

        image_paths = []
        grouped_paths = []
        location_labels = []
        location_indices = []
        pose_targets = []
        skipped_no_pose = 0
        skipped_no_source = 0

        for idx in candidate_indexes:
            if not (0 <= idx < len(self.images)) or idx in deleted:
                continue

            paths = self._location_source_paths_for_index(
                idx, selected_sources, virtual_type, num_sources, temporal_interval)
            if not paths:
                skipped_no_source += 1
                continue

            pose_value = None
            if use_pose:
                pose = self.pose_manager.get_pose(idx, prefer=pose_source)
                if pose is None:
                    skipped_no_pose += 1
                    continue
                pose_value = [float(pose.x), float(pose.y), float(pose.theta)]

            if use_class:
                location = self.location_annotations[idx]
                location_labels.append(location)
                location_indices.append(location_to_index[location])
            if use_pose:
                pose_targets.append(pose_value)
            image_paths.append(paths[0])
            grouped_paths.append(paths)

        return {
            'image_paths': image_paths,
            'grouped_paths': grouped_paths,
            'location_labels': location_labels,
            'location_indices': location_indices,
            'location_to_index': location_to_index,
            'pose_targets': pose_targets,
            'skipped_no_pose': skipped_no_pose,
            'skipped_no_source': skipped_no_source,
        }

    def _train_location_model_internal(self, model_type, train_loader, val_loader, num_classes,
                                       training_config, progress_callback, dataset_info=None):
        """位置モデル学習（model_training.train_location_model へ委譲）

        クラス分類 / 座標・姿勢回帰 / 両方、および複数画像入力に対応する。
        """
        dataset_info = dataset_info or {}
        output_mode = training_config.get('output_mode', 'class')
        heads = str(output_mode).split('_')
        use_pose = 'pose' in heads
        use_grid = 'grid' in heads
        needs_pose = use_pose or use_grid

        # 保存ディレクトリとファイル名（モデルタイプを必ず含める）
        models_dir = os.path.join(APP_DIR_PATH, MODELS_DIR_NAME)
        os.makedirs(models_dir, exist_ok=True)
        custom_name = (training_config.get('model_name') or '').strip()
        if not custom_name:
            save_name = f"{model_type}_{datetime.now().strftime('%Y%m%d_%H%M%S')}"
        elif custom_name.startswith(model_type):
            save_name = custom_name
        else:
            save_name = f"{model_type}_{custom_name}"

        # チェックポイントへ保存する入出力構成（推論時に同じ入力構成を再現するため）
        location_config = {
            'selected_sources': training_config.get('selected_sources'),
            'virtual_source_type': training_config.get('virtual_source_type'),
            'temporal_interval': training_config.get('temporal_interval', 10),
            'pose_source': training_config.get('pose_source') if needs_pose else None,
            'pose_norm': dataset_info.get('pose_norm') if use_pose else None,
            'include_heading': bool(dataset_info.get('include_heading')) if use_pose else False,
            'downscale_factor': float(training_config.get('downscale_factor', 1.0)),
            'downscale_mode': training_config.get('downscale_mode', 'resize'),
            'grid_config': dataset_info.get('grid_config') if use_grid else None,
            'num_grid_classes': int(dataset_info.get('num_grid_classes') or 0) if use_grid else 0,
        }

        return train_location_model(
            model_name=model_type,
            train_loader=train_loader,
            val_loader=val_loader,
            num_classes=num_classes,
            num_epochs=training_config['num_epochs'],
            learning_rate=training_config['learning_rate'],
            weight_decay=1e-4,
            save_dir=models_dir,
            progress_callback=progress_callback,
            pretrained=True,
            use_early_stopping=training_config['use_early_stopping'],
            patience=training_config['patience'],
            custom_model_name=save_name,
            num_sources=training_config.get('num_sources', 1),
            fusion_method=training_config.get('fusion_method', 'concat'),
            output_mode=output_mode,
            pose_dim=int(dataset_info.get('pose_dim') or 4),
            pose_loss_weight=training_config.get('pose_loss_weight', 1.0),
            location_config=location_config,
            input_size=dataset_info.get('actual_image_size'),
            num_grid_classes=int(dataset_info.get('num_grid_classes') or 0) if use_grid else 0,
            grid_loss_weight=training_config.get('grid_loss_weight', 1.0),
            grid_top_n=int(getattr(self, 'location_topn', 3)),
            grid_label_sigma=float(training_config.get('grid_label_sigma', 1.0)),
            grid_class_balance=bool(training_config.get('grid_class_balance', True)),
        )

    def _initialize_location_model(self, model_type, num_classes, device):
        """位置モデルの初期化"""
        
        # モデルを初期化（既存のget_model関数を使用）
        if 'donkey_location' in model_type:
            model = get_model(model_type, pretrained=True)
            model.classifier = nn.Linear(50, num_classes)  # 出力層を置き換え
        else:
            # TIMMバックボーン系の位置モデル（resnet18_location含む）は
            # 共通してregressorヘッドを持つため、クラス数に合わせて置き換える
            model = get_model(model_type, pretrained=True)
            if hasattr(model, 'regressor'):
                in_features = model.regressor.in_features if hasattr(model.regressor, 'in_features') else model.regressor[0].in_features
                model.regressor = nn.Linear(in_features, num_classes)
        
        return model.to(device)

    def _save_location_model_metadata(self, model_path, num_classes, actual_classes, location_mapping):
        """位置モデルのメタデータを保存"""
        
        checkpoint = torch.load(model_path, map_location='cpu')
        checkpoint['num_classes'] = num_classes
        checkpoint['actual_classes'] = actual_classes
        checkpoint['location_mapping'] = location_mapping
        torch.save(checkpoint, model_path)

    def _log_location_training(self, model_type, training_results, training_config, dataset_info):
        """位置推論モデルの学習結果をMLflowに記録"""
        
        try:
            # MLflowManagerが初期化されていない場合は初期化
            if not hasattr(self, 'mlflow_manager'):
                self.mlflow_manager = MLflowManager(self.folder_path)
            
            # メトリクスを準備
            metrics = {
                "best_val_loss": training_results.get('best_val_loss', 0.0),
                "best_val_acc": training_results.get('best_val_acc', 0.0),
                "final_train_loss": training_results['train_losses'][-1] if 'train_losses' in training_results else 0.0,
                "final_val_loss": training_results['val_losses'][-1] if 'val_losses' in training_results else 0.0,
                "final_train_acc": training_results['train_accuracies'][-1] if 'train_accuracies' in training_results else 0.0,
                "final_val_acc": training_results['val_accuracies'][-1] if 'val_accuracies' in training_results else 0.0,
                "train_losses": training_results.get('train_losses', []),
                "val_losses": training_results.get('val_losses', []),
                "train_accuracies": training_results.get('train_accuracies', []),
                "val_accuracies": training_results.get('val_accuracies', []),
                "status": "early_stopped" if training_results.get('early_stopped', False) else "completed"
            }
            output_mode = training_config.get('output_mode', 'class')
            heads = str(output_mode).split('_')
            if 'pose' in heads:
                metrics["best_val_pos_error_m"] = training_results.get('best_val_pos_error') or 0.0
                metrics["best_val_heading_error_deg"] = training_results.get('best_val_heading_error') or 0.0
                metrics["position_error_mean"] = training_results.get('best_val_pos_error') or 0.0
                metrics["train_pos_errors"] = training_results.get('train_pos_errors', [])
                metrics["val_pos_errors"] = training_results.get('val_pos_errors', [])
            if 'grid' in heads:
                metrics["best_val_grid_acc"] = training_results.get('best_val_grid_acc') or 0.0
                metrics["best_val_grid_top1_error_m"] = training_results.get('best_val_grid_error') or 0.0
                metrics["best_val_grid_weighted_error_m"] = training_results.get('best_val_grid_weighted_error') or 0.0
                metrics["val_grid_accuracies"] = training_results.get('val_grid_accuracies', [])
                metrics["val_grid_errors"] = training_results.get('val_grid_errors', [])

            _cs = {'class': 'classification', 'pose': 'map_xy_theta', 'grid': 'map_grid_cell'}
            _em = {'class': 'cnn_classification', 'pose': 'cnn_pose_regression', 'grid': 'cnn_grid_classification'}
            coordinate_system = '+'.join(_cs[h] for h in heads if h in _cs)
            estimation_method = 'cnn_multitask' if len(heads) > 1 else _em.get(heads[0], 'cnn_classification')

            # 学習パラメータを準備
            training_params = {
                "model_type": model_type,
                "model_name": training_config.get('model_name', ''),
                "comment": training_config.get('comment', ''),
                "num_epochs": training_config['num_epochs'],
                "completed_epochs": training_results.get('completed_epochs', training_config['num_epochs']),
                "learning_rate": training_config['learning_rate'],
                "batch_size": training_config['batch_size'],
                "use_early_stopping": training_config['use_early_stopping'],
                "patience": training_config['patience'],
                "early_stopped": training_results.get('early_stopped', False),
                "augmentation_enabled": training_config['use_augmentation'],
                "coordinate_system": coordinate_system,  # 位置推論特有
                "estimation_method": estimation_method,  # 位置推論特有
                "fixed_classes": dataset_info['num_classes'],
                "actual_classes": dataset_info['actual_classes'],
                "output_mode": output_mode,
                "num_sources": training_config.get('num_sources', 1),
                "fusion_method": training_config.get('fusion_method') if training_config.get('num_sources', 1) > 1 else None,
                "selected_sources": ",".join(training_config.get('selected_sources') or []),
                "virtual_source_type": training_config.get('virtual_source_type') or "none",
                "temporal_interval": training_config.get('temporal_interval', 10),
                "pose_source": training_config.get('pose_source') or "none",
                "include_heading": training_config.get('include_heading', False),
                "pose_loss_weight": training_config.get('pose_loss_weight', 1.0),
                "grid_cell_size": training_config.get('grid_cell_size') if 'grid' in heads else None,
                "num_grid_classes": dataset_info.get('num_grid_classes') if 'grid' in heads else None,
                "grid_loss_weight": training_config.get('grid_loss_weight') if 'grid' in heads else None,
                "grid_label_sigma": training_config.get('grid_label_sigma') if 'grid' in heads else None,
                "grid_class_balance": training_config.get('grid_class_balance') if 'grid' in heads else None,
                "data_folder": self.folder_path if hasattr(self, 'folder_path') and self.folder_path else "unknown"
            }

            # MLflowに記録
            success = self.mlflow_manager.log_position_estimation_model(
                model_path=training_results['best_model_path'],
                training_params=training_params,
                metrics=metrics,
                dataset_info=dataset_info
            )
            
            if success:
                return "MLflowに学習履歴を記録しました。\n「MLflow比較」ボタンで結果を確認できます。"
            else:
                return "MLflowへの記録中にエラーが発生しました。"
                
        except ImportError:
            return "MLflowがインストールされていないため、学習履歴は記録されませんでした。\npip install mlflow でインストールできます。"
        except Exception as e:
            print(f"MLflow記録エラー: {e}")
            return f"MLflowへの記録中にエラーが発生しました: {str(e)}"

    def _show_location_training_success(self, model_type, training_results, training_config, dataset_info, mlflow_info):
        """位置モデル学習成功メッセージを表示"""
        
        # Early Stopping情報
        early_stopping_info = ""
        if training_config['use_early_stopping']:
            if training_results.get('early_stopped', False):
                early_stopping_info = f"Early Stopping: {training_results.get('stopped_epoch', 0)}エポックで停止\n"
            else:
                early_stopping_info = f"Early Stopping: 発動せず (忍耐値: {training_config['patience']})\n"
        
        # 学習時間情報
        time_info = ""
        if 'total_training_time' in training_results:
            from model_training import format_time
            total_time_str = format_time(training_results['total_training_time'])
            avg_epoch_time_str = format_time(training_results.get('avg_epoch_time', 0))
            time_info = f"学習時間: {total_time_str} (平均エポック時間: {avg_epoch_time_str})\n"
        
        # 学習完了メッセージ（2カラムレイアウト）
        dialog = QDialog(self)
        dialog.setWindowTitle(get_text('dlg_training_complete'))
        dialog.setMinimumWidth(700)
        dlg_layout = QVBoxLayout(dialog)

        title_label = QLabel(f"{model_type} 位置モデルを学習し保存しました: {os.path.basename(training_results['best_model_path'])}")
        title_label.setStyleSheet("font-weight: bold;")
        dlg_layout.addWidget(title_label)

        columns_layout = QHBoxLayout()

        output_mode = training_config.get('output_mode', 'class')
        heads = str(output_mode).split('_')
        use_class = 'class' in heads
        use_pose = 'pose' in heads
        use_grid = 'grid' in heads

        # 左カラム: 学習結果
        left_group = QGroupBox("学習結果")
        left_layout = QVBoxLayout(left_group)
        left_layout.addWidget(QLabel(f"最良検証損失: {training_results['best_val_loss']:.6f}"))
        if use_class:
            left_layout.addWidget(QLabel(f"最良検証精度: {training_results['best_val_acc']:.2f}%"))
        if use_pose:
            pos_err = training_results.get('best_val_pos_error')
            if pos_err is not None:
                left_layout.addWidget(QLabel(get_text('label_location_result_pos_error', f"{pos_err:.3f}")))
            head_err = training_results.get('best_val_heading_error')
            if head_err is not None and training_config.get('include_heading'):
                left_layout.addWidget(QLabel(get_text('label_location_result_heading_error', f"{head_err:.1f}")))
        if use_grid:
            g_acc = training_results.get('best_val_grid_acc')
            g_err = training_results.get('best_val_grid_error')
            g_werr = training_results.get('best_val_grid_weighted_error')
            if g_acc is not None:
                left_layout.addWidget(QLabel(get_text('label_location_result_grid_acc', f"{g_acc:.1f}")))
            if g_err is not None and g_werr is not None:
                left_layout.addWidget(QLabel(get_text('label_location_result_grid_error',
                                                      f"{g_err:.3f}", training_results.get('grid_top_n', 3),
                                                      f"{g_werr:.3f}")))
        left_layout.addWidget(QLabel(f"実施エポック数: {training_results['completed_epochs']}/{training_config['num_epochs']}"))
        if early_stopping_info:
            left_layout.addWidget(QLabel(early_stopping_info.strip()))
        if time_info:
            left_layout.addWidget(QLabel(time_info.strip()))
        left_layout.addWidget(QLabel(f"学習データ数: {dataset_info['image_paths_count']}枚"))
        skipped = dataset_info.get('skipped_no_pose', 0) + dataset_info.get('skipped_no_source', 0)
        if skipped:
            left_layout.addWidget(QLabel(get_text('label_location_result_skipped',
                                                  dataset_info.get('skipped_no_pose', 0),
                                                  dataset_info.get('skipped_no_source', 0))))
        left_layout.addStretch()

        # 右カラム: 学習設定
        right_group = QGroupBox("学習設定")
        right_layout = QVBoxLayout(right_group)
        mode_desc = " + ".join(get_text(f'opt_location_head_{h}') for h in heads)
        right_layout.addWidget(QLabel(get_text('label_location_result_output_mode', mode_desc)))
        if use_grid:
            gcfg = training_results.get('grid_config') or {}
            right_layout.addWidget(QLabel(get_text('label_location_result_grid',
                                                   training_config.get('grid_cell_size') or '-',
                                                   gcfg.get('nx', '-'), gcfg.get('ny', '-'),
                                                   gcfg.get('num_cells', '-'))))
        if use_class:
            right_layout.addWidget(QLabel(f"出力クラス数: {dataset_info['num_classes']} (実際の位置クラス数: {dataset_info['actual_classes']})"))
        if use_pose:
            right_layout.addWidget(QLabel(get_text('label_location_result_pose_source',
                                                   training_config.get('pose_source') or '-',
                                                   'ON' if training_config.get('include_heading') else 'OFF')))
        n_src = training_config.get('num_sources', 1)
        src_desc = ", ".join(training_config.get('selected_sources') or [])
        if training_config.get('virtual_source_type'):
            src_desc += f" / {training_config['virtual_source_type']} x{n_src}"
        elif n_src > 1:
            src_desc += f" / {training_config.get('fusion_method', 'concat')}"
        right_layout.addWidget(QLabel(get_text('label_location_result_inputs', n_src, src_desc)))
        in_size = dataset_info.get('input_size')
        if in_size:
            mode = training_config.get('downscale_mode', 'resize')
            factor = training_config.get('downscale_factor', 1.0)
            res_desc = f"{int(factor * 100)}% / {mode}" if factor < 1.0 else "100%"
            right_layout.addWidget(QLabel(get_text('label_location_result_input_size',
                                                   in_size[1], in_size[0], res_desc)))
        right_layout.addWidget(QLabel(f"学習率: {training_config['learning_rate']}"))
        right_layout.addWidget(QLabel(f"バッチサイズ: {training_config['batch_size']}"))
        right_layout.addWidget(QLabel(f"データオーグメンテーション: {'有効' if training_config['use_augmentation'] else '無効'}"))
        right_layout.addStretch()

        columns_layout.addWidget(left_group)
        columns_layout.addWidget(right_group)
        dlg_layout.addLayout(columns_layout)

        if mlflow_info:
            mlflow_label = QLabel(mlflow_info)
            mlflow_label.setWordWrap(True)
            dlg_layout.addWidget(mlflow_label)

        # ボタン
        button_layout = QHBoxLayout()
        button_layout.addStretch()
        mlflow_button = QPushButton(get_text('btn_open_mlflow'))
        ok_button = QPushButton("OK")
        ok_button.setDefault(True)
        ok_button.clicked.connect(dialog.accept)
        button_layout.addWidget(mlflow_button)
        button_layout.addWidget(ok_button)
        dlg_layout.addLayout(button_layout)

        clicked_mlflow = [False]
        def on_mlflow_clicked():
            clicked_mlflow[0] = True
            dialog.accept()
        mlflow_button.clicked.connect(on_mlflow_clicked)

        dialog.exec_()

        if clicked_mlflow[0]:
            self.mlflow_manager.open_ui()


    def train_and_save_waypoint_model(self):
        """ウェイポイント推論モデルの学習"""

        if not self.images or not self.waypoint_annotations:
            QMessageBox.warning(self, get_text('dlg_warning'), get_text('msg_need_waypoint_annotations_first'))
            return

        # 有効なウェイポイントアノテーションをチェック
        valid_waypoint_count = 0
        waypoint_counts = []
        deleted_count = 0

        for idx, waypoints in self.waypoint_annotations.items():
            # 削除マークされていないかチェック（actual_indexで判定）
            if hasattr(self, 'deleted_indexes') and idx in self.deleted_indexes:
                deleted_count += 1
                continue

            if waypoints and len(waypoints) > 0:
                valid_waypoint_count += 1
                waypoint_counts.append(len(waypoints))

        if valid_waypoint_count < 5:
            QMessageBox.warning(self, get_text('dlg_warning'), get_text('msg_need_waypoint_annotations', valid_waypoint_count))
            return

        # ウェイポイント数の統計
        if not waypoint_counts:
            QMessageBox.warning(self, get_text('dlg_warning'), get_text('msg_no_valid_waypoint_annotations'))
            return

        most_common_waypoint_count = max(set(waypoint_counts), key=waypoint_counts.count)

        # 選択されたモデル
        model_type = self.waypoint_model_combo.currentText()

        # アノテーション統計情報を収集（削除済みマークを考慮）
        total_images = len(self.images)
        annotated_images = len(self.waypoint_annotations)

        # 学習設定ダイアログを表示
        training_settings = self._create_waypoint_training_dialog(
            model_type, most_common_waypoint_count, total_images, annotated_images,
            valid_waypoint_count, deleted_count
        )

        if not training_settings.exec_():
            return

        # 設定値の取得
        training_config = self._get_waypoint_training_config(training_settings)

        try:
            # データの準備
            image_data = self._prepare_waypoint_training_data(training_config['num_waypoints'])

            if not image_data['image_paths']:
                QMessageBox.warning(self, get_text('dlg_warning'), get_text('msg_no_valid_waypoint_annotations'))
                return

            # スキップされた画像がある場合、ユーザーに通知
            if image_data['skipped_images']:
                skipped_count = len(image_data['skipped_images'])
                skipped_msg = get_text('msg_skipped_images_header', skipped_count)

                # 最初の10件のみ表示
                for i, skipped in enumerate(image_data['skipped_images'][:10]):
                    img_name = os.path.basename(skipped['path'])
                    skipped_msg += get_text('msg_skipped_images_item', skipped['index'], img_name, skipped['reason'])

                if skipped_count > 10:
                    skipped_msg += get_text('msg_skipped_images_more', skipped_count - 10)

                skipped_msg += get_text('msg_skipped_images_footer', len(image_data['image_paths']))

                reply = QMessageBox.question(self, get_text('dlg_confirm'), skipped_msg,
                                            QMessageBox.Yes | QMessageBox.No,
                                            QMessageBox.Yes)
                if reply == QMessageBox.No:
                    return

            # 進捗ダイアログを表示
            progress = QProgressDialog(
                get_text('msg_preparing_waypoint_training', model_type),
                get_text('btn_cancel'), 0, 100, self
            )
            progress.setWindowTitle(get_text('dlg_waypoint_model_training'))
            progress.setWindowModality(Qt.WindowModal)
            progress.show()
            QApplication.processEvents()

            # データセット作成
            train_loader, val_loader, dataset_info = create_waypoint_datasets(
                image_paths=image_data['image_paths'],
                waypoint_labels=image_data['waypoint_coordinates'],
                val_split=0.2,
                model_name=model_type,
                batch_size=training_config['batch_size'],
                use_augmentation=training_config['use_augmentation'],
                num_waypoints=training_config['num_waypoints']
            )

            progress.setValue(20)
            progress.setLabelText(get_text('msg_initializing_model_waypoints', model_type, training_config['num_waypoints']))
            QApplication.processEvents()

            # 進捗コールバック関数
            def update_progress(current, total, message=None):
                if message:
                    progress.setLabelText(message)
                progress.setValue(20 + int(current * 70 / total))
                QApplication.processEvents()
                return not progress.wasCanceled()

            # モデル学習
            training_results = self._train_waypoint_model_internal(
                model_type=model_type,
                train_loader=train_loader,
                val_loader=val_loader,
                num_waypoints=training_config['num_waypoints'],
                training_config=training_config,
                progress_callback=update_progress
            )

            # モデルのメタデータ保存
            self._save_waypoint_model_metadata(
                training_results['best_model_path'],
                training_config['num_waypoints']
            )

            # 学習曲線グラフを保存
            progress.setValue(92)
            progress.setLabelText(get_text('msg_saving_training_curve'))
            QApplication.processEvents()

            self._save_waypoint_training_curve(
                training_results['best_model_path'],
                training_results['training_history']
            )

            progress.setValue(95)
            progress.setLabelText(get_text('msg_recording_mlflow'))
            QApplication.processEvents()

            # MLflowに結果を記録
            mlflow_info = self._log_waypoint_training(
                model_type=model_type,
                training_results=training_results,
                training_config=training_config,
                dataset_info={
                    "total_annotations": len(self.waypoint_annotations),
                    "used_samples": len(image_data['image_paths']),
                    "train_samples": dataset_info['train_samples'],
                    "val_samples": dataset_info['val_samples'],
                    "input_shape": dataset_info['actual_image_size'],
                    "num_waypoints": training_config['num_waypoints']
                }
            )

            # モデルリストを更新
            self.refresh_waypoint_model_list()

            progress.setValue(100)
            progress.close()

            # 学習完了メッセージ
            self._show_waypoint_training_success(
                model_type=model_type,
                training_results=training_results,
                training_config=training_config,
                dataset_info={
                    "image_paths_count": len(image_data['image_paths']),
                    "num_waypoints": training_config['num_waypoints']
                },
                mlflow_info=mlflow_info
            )

        except Exception as e:
            if 'progress' in locals():
                progress.close()
            traceback.print_exc()
            QMessageBox.critical(self, get_text('dlg_error'), get_text('msg_waypoint_training_error', str(e)))

    def _train_waypoint_model_internal(self, model_type, train_loader, val_loader, num_waypoints, training_config, progress_callback):
        """ウェイポイントモデルの内部学習ロジック"""
        device = torch.device('cuda' if torch.cuda.is_available() else 'cpu')

        # モデル初期化
        model = self._initialize_waypoint_model(model_type, num_waypoints, device)

        # 学習パラメータ設定
        criterion = nn.MSELoss()  # 回帰問題のMSE損失
        optimizer = torch.optim.Adam(model.parameters(), lr=training_config['learning_rate'])
        scheduler = torch.optim.lr_scheduler.ReduceLROnPlateau(
            optimizer, mode='min', factor=0.5, patience=5, verbose=True
        )

        # Early Stopping設定
        early_stopping = None
        if training_config['use_early_stopping']:
            from model_training import EarlyStopping
            early_stopping = EarlyStopping(patience=training_config['patience'], min_delta=0.001)

        # 学習ループ
        best_val_loss = float('inf')
        best_model_path = None
        training_history = {
            'train_loss': [],
            'val_loss': [],
            'waypoint_losses': []  # 各waypointごとのloss履歴
        }

        # 保存ディレクトリとタイムスタンプ
        models_dir = os.path.join(APP_DIR_PATH, MODELS_DIR_NAME)
        os.makedirs(models_dir, exist_ok=True)
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")

        import time
        start_time = time.time()
        epoch_times = []

        for epoch in range(training_config['num_epochs']):
            epoch_start_time = time.time()

            # トレーニング
            model.train()
            train_loss = 0.0

            for batch_idx, (images, targets) in enumerate(train_loader):
                images, targets = images.to(device), targets.to(device)

                optimizer.zero_grad()
                outputs = model(images)
                loss = criterion(outputs, targets)
                loss.backward()
                optimizer.step()

                train_loss += loss.item()

            train_loss /= len(train_loader)

            # 検証
            model.eval()
            val_loss = 0.0
            waypoint_losses = [0.0] * (num_waypoints * 2)  # 各x, y座標のloss

            with torch.no_grad():
                for images, targets in val_loader:
                    images, targets = images.to(device), targets.to(device)
                    outputs = model(images)
                    loss = criterion(outputs, targets)
                    val_loss += loss.item()

                    # 各waypoint座標ごとのlossを計算
                    for i in range(num_waypoints * 2):
                        coord_loss = ((outputs[:, i] - targets[:, i]) ** 2).mean().item()
                        waypoint_losses[i] += coord_loss

            val_loss /= len(val_loader)
            waypoint_losses = [wl / len(val_loader) for wl in waypoint_losses]

            training_history['train_loss'].append(train_loss)
            training_history['val_loss'].append(val_loss)
            training_history['waypoint_losses'].append(waypoint_losses)

            # 学習率スケジューラー更新
            scheduler.step(val_loss)

            # ベストモデル保存
            if val_loss < best_val_loss:
                best_val_loss = val_loss
                # 最初のエポックで保存パスを設定（タイムスタンプを固定）
                if best_model_path is None:
                    # カスタムモデル名が指定されていればそれを使用、ただしモデルタイプを必ず含める
                    custom_name = training_config.get('model_name', '').strip()
                    if custom_name:
                        # カスタム名がある場合: モデルタイプ_カスタム名 の形式
                        save_name = f"{model_type}_{custom_name}"
                    else:
                        # カスタム名がない場合: モデルタイプのみ
                        save_name = model_type
                    model_filename = f"{save_name}.pth"
                    best_model_path = os.path.join(models_dir, model_filename)

                torch.save({
                    'model_state_dict': model.state_dict(),
                    'model_type': model_type,
                    'num_waypoints': num_waypoints,
                    'epoch': epoch,
                    'val_loss': val_loss
                }, best_model_path)

            # 進捗更新
            epoch_time = time.time() - epoch_start_time
            epoch_times.append(epoch_time)

            message = f"Epoch {epoch+1}/{training_config['num_epochs']}: 訓練損失={train_loss:.6f}, 検証損失={val_loss:.6f}"
            if not progress_callback(epoch + 1, training_config['num_epochs'], message):
                break

            # Early Stoppingチェック
            if early_stopping and early_stopping(val_loss):
                break

        total_time = time.time() - start_time
        avg_epoch_time = sum(epoch_times) / len(epoch_times) if epoch_times else 0

        return {
            'best_model_path': best_model_path,
            'best_val_loss': best_val_loss,
            'completed_epochs': len(training_history['train_loss']),
            'training_history': training_history,
            'total_training_time': total_time,
            'avg_epoch_time': avg_epoch_time,
            'early_stopped': early_stopping.early_stop if early_stopping else False,
            'stopped_epoch': len(training_history['train_loss']) if early_stopping and early_stopping.early_stop else None
        }

    def _initialize_waypoint_model(self, model_type, num_waypoints, device):
        """ウェイポイントモデルを初期化"""
        from model_catalog import get_model

        # モデルのロード
        model = get_model(model_type, pretrained=True, input_size=(224, 224))
        model.num_waypoints = num_waypoints  # ウェイポイント数を設定
        model.to(device)

        return model

    def _save_waypoint_model_metadata(self, model_path, num_waypoints):
        """ウェイポイントモデルのメタデータを保存"""
        checkpoint = torch.load(model_path, map_location='cpu')
        checkpoint['num_waypoints'] = num_waypoints
        torch.save(checkpoint, model_path)

    def _save_waypoint_training_curve(self, model_path, training_history):
        """ウェイポイントモデルの学習曲線をグラフとして保存"""
        try:
            import matplotlib.pyplot as plt
            import numpy as np

            # グラフのファイル名を生成
            graph_path = model_path.replace('.pth', '_training_curve.png')

            epochs = range(1, len(training_history['train_loss']) + 1)

            # waypoint詳細lossがあるかチェック
            has_waypoint_losses = 'waypoint_losses' in training_history and training_history['waypoint_losses']

            if has_waypoint_losses:
                # 3列のサブプロット: 全体loss、waypointごとのloss、座標ごとのloss
                fig = plt.figure(figsize=(20, 6))
                gs = fig.add_gridspec(1, 3, hspace=0.3, wspace=0.3)
                ax1 = fig.add_subplot(gs[0, 0])
                ax2 = fig.add_subplot(gs[0, 1])
                ax3 = fig.add_subplot(gs[0, 2])
            else:
                # waypoint詳細lossがない場合は全体lossのみ
                fig, ax1 = plt.subplots(1, 1, figsize=(10, 6))

            # ===== グラフ1: 全体の学習曲線 =====
            ax1.plot(epochs, training_history['train_loss'], 'b-', label='Training Loss', linewidth=2)
            ax1.plot(epochs, training_history['val_loss'], 'r-', label='Validation Loss', linewidth=2)

            # 最小検証損失のエポックをマーク
            min_val_loss_epoch = training_history['val_loss'].index(min(training_history['val_loss'])) + 1
            min_val_loss = min(training_history['val_loss'])
            ax1.axvline(x=min_val_loss_epoch, color='g', linestyle='--', alpha=0.7,
                       label=f'Best (Epoch {min_val_loss_epoch})')

            ax1.set_title('Overall Training Curve', fontsize=14, fontweight='bold')
            ax1.set_xlabel('Epoch', fontsize=11)
            ax1.set_ylabel('Loss (MSE)', fontsize=11)
            ax1.legend(fontsize=10, loc='upper right')
            ax1.grid(True, alpha=0.3)

            # ===== グラフ2 & 3: 各waypointごとの詳細loss =====
            if has_waypoint_losses:
                waypoint_losses_array = np.array(training_history['waypoint_losses'])
                num_coords = waypoint_losses_array.shape[1]
                num_waypoints = num_coords // 2

                colors = plt.cm.tab10(np.linspace(0, 1, num_waypoints))

                # グラフ2: 各waypointの合計loss (x + y)
                for wp_idx in range(num_waypoints):
                    x_idx = wp_idx * 2
                    y_idx = wp_idx * 2 + 1
                    waypoint_total_loss = waypoint_losses_array[:, x_idx] + waypoint_losses_array[:, y_idx]
                    ax2.plot(epochs, waypoint_total_loss, color=colors[wp_idx],
                            label=f'Waypoint {wp_idx + 1}', linewidth=2)

                ax2.set_title('Loss per Waypoint (X + Y)', fontsize=14, fontweight='bold')
                ax2.set_xlabel('Epoch', fontsize=11)
                ax2.set_ylabel('Loss (MSE)', fontsize=11)
                ax2.legend(fontsize=10, loc='upper right')
                ax2.grid(True, alpha=0.3)

                # グラフ3: 各座標(x, y)のloss
                for wp_idx in range(num_waypoints):
                    x_idx = wp_idx * 2
                    y_idx = wp_idx * 2 + 1
                    ax3.plot(epochs, waypoint_losses_array[:, x_idx], color=colors[wp_idx],
                            linestyle='-', label=f'WP{wp_idx + 1}-X', linewidth=1.5, alpha=0.8)
                    ax3.plot(epochs, waypoint_losses_array[:, y_idx], color=colors[wp_idx],
                            linestyle='--', label=f'WP{wp_idx + 1}-Y', linewidth=1.5, alpha=0.8)

                ax3.set_title('Loss per Coordinate (X: solid, Y: dashed)', fontsize=14, fontweight='bold')
                ax3.set_xlabel('Epoch', fontsize=11)
                ax3.set_ylabel('Loss (MSE)', fontsize=11)
                ax3.legend(fontsize=9, loc='upper right', ncol=2)
                ax3.grid(True, alpha=0.3)

            # 全体のタイトル
            fig.suptitle('Waypoint Model Training Analysis', fontsize=16, fontweight='bold', y=0.98)

            # グラフを保存
            plt.tight_layout(rect=[0, 0, 1, 0.96])
            plt.savefig(graph_path, dpi=150, bbox_inches='tight')
            plt.close()

            print(f"学習曲線を保存しました: {graph_path}")

        except Exception as e:
            print(f"学習曲線の保存に失敗しました: {e}")
            import traceback
            traceback.print_exc()

    def _log_waypoint_training(self, model_type, training_results, training_config, dataset_info):
        """ウェイポイント推論モデルの学習結果をMLflowに記録"""

        try:
            # MLflowManagerが初期化されていない場合は初期化
            if not hasattr(self, 'mlflow_manager'):
                self.mlflow_manager = MLflowManager(self.folder_path)

            # 学習パラメータを記録
            params = {
                'model_type': model_type,
                'num_waypoints': training_config['num_waypoints'],
                'learning_rate': training_config['learning_rate'],
                'batch_size': training_config['batch_size'],
                'num_epochs': training_config['num_epochs'],
                'use_augmentation': training_config['use_augmentation'],
                'use_early_stopping': training_config['use_early_stopping']
            }

            if training_config['use_early_stopping']:
                params['patience'] = training_config['patience']

            # メトリクスを記録
            metrics = {
                'best_val_loss': training_results['best_val_loss'],
                'completed_epochs': training_results['completed_epochs'],
                'total_training_time': training_results['total_training_time'],
                'avg_epoch_time': training_results['avg_epoch_time'],
                'train_samples': dataset_info['train_samples'],
                'val_samples': dataset_info['val_samples'],
                'total_annotations': dataset_info['total_annotations'],
                'used_samples': dataset_info['used_samples']
            }

            # アーティファクトを記録
            artifacts = {
                'model_path': training_results['best_model_path']
            }

            # MLflowに記録 - ウェイポイント専用メソッドを使用
            run_info = self.mlflow_manager.log_waypoint_regression_model(
                model_path=training_results['best_model_path'],
                training_params={
                    'model_type': model_type,
                    'num_waypoints': training_config['num_waypoints'],
                    'learning_rate': training_config['learning_rate'],
                    'batch_size': training_config['batch_size'],
                    'num_epochs': training_config['num_epochs'],
                    'completed_epochs': training_results['completed_epochs'],
                    'use_early_stopping': training_config['use_early_stopping'],
                    'patience': training_config['patience'] if training_config['use_early_stopping'] else 0,
                    'use_augmentation': training_config['use_augmentation'],
                    'data_folder': self.folder_path
                },
                metrics={
                    'best_val_loss': training_results['best_val_loss'],
                    'completed_epochs': training_results['completed_epochs'],
                    'total_training_time': training_results['total_training_time'],
                    'avg_epoch_time': training_results['avg_epoch_time'],
                    'status': 'completed'
                },
                dataset_info={
                    'train_samples': dataset_info['train_samples'],
                    'val_samples': dataset_info['val_samples'],
                    'total_annotations': dataset_info['total_annotations'],
                    'used_samples': dataset_info['used_samples']
                }
            )

            return f"MLflow Run ID: {run_info['run_id']}"

        except Exception as e:
            print(f"MLflow記録エラー: {e}")
            return "MLflow記録に失敗しました"

    def _show_waypoint_training_success(self, model_type, training_results, training_config, dataset_info, mlflow_info):
        """ウェイポイントモデル学習成功メッセージを表示"""

        # Early Stopping情報
        early_stopping_info = ""
        if training_config['use_early_stopping']:
            if training_results.get('early_stopped', False):
                early_stopping_info = f"Early Stopping: {training_results.get('stopped_epoch', 0)}エポックで停止\n"
            else:
                early_stopping_info = f"Early Stopping: 発動せず (忍耐値: {training_config['patience']})\n"

        # 学習時間情報
        time_info = ""
        if 'total_training_time' in training_results:
            from model_training import format_time
            total_time_str = format_time(training_results['total_training_time'])
            avg_epoch_time_str = format_time(training_results.get('avg_epoch_time', 0))
            time_info = f"学習時間: {total_time_str} (平均エポック時間: {avg_epoch_time_str})\n"

        # 学習完了メッセージ（2カラムレイアウト）
        dialog = QDialog(self)
        dialog.setWindowTitle(get_text('dlg_training_complete'))
        dialog.setMinimumWidth(700)
        dlg_layout = QVBoxLayout(dialog)

        title_label = QLabel(f"{model_type} ウェイポイントモデルを学習し保存しました: {os.path.basename(training_results['best_model_path'])}")
        title_label.setStyleSheet("font-weight: bold;")
        dlg_layout.addWidget(title_label)

        columns_layout = QHBoxLayout()

        # 左カラム: 学習結果
        left_group = QGroupBox("学習結果")
        left_layout = QVBoxLayout(left_group)
        left_layout.addWidget(QLabel(f"最良検証損失: {training_results['best_val_loss']:.6f}"))
        left_layout.addWidget(QLabel(f"実施エポック数: {training_results['completed_epochs']}/{training_config['num_epochs']}"))
        if early_stopping_info:
            left_layout.addWidget(QLabel(early_stopping_info.strip()))
        if time_info:
            left_layout.addWidget(QLabel(time_info.strip()))
        left_layout.addWidget(QLabel(f"学習データ数: {dataset_info['image_paths_count']}枚"))
        left_layout.addStretch()

        # 右カラム: 学習設定
        right_group = QGroupBox("学習設定")
        right_layout = QVBoxLayout(right_group)
        right_layout.addWidget(QLabel(f"ウェイポイント数: {dataset_info['num_waypoints']}"))
        right_layout.addWidget(QLabel(f"学習率: {training_config['learning_rate']}"))
        right_layout.addWidget(QLabel(f"バッチサイズ: {training_config['batch_size']}"))
        right_layout.addWidget(QLabel(f"データオーグメンテーション: {'有効' if training_config['use_augmentation'] else '無効'}"))
        right_layout.addStretch()

        columns_layout.addWidget(left_group)
        columns_layout.addWidget(right_group)
        dlg_layout.addLayout(columns_layout)

        if mlflow_info:
            mlflow_label = QLabel(mlflow_info)
            mlflow_label.setWordWrap(True)
            dlg_layout.addWidget(mlflow_label)

        # ボタン
        button_layout = QHBoxLayout()
        button_layout.addStretch()
        mlflow_button = QPushButton(get_text('btn_open_mlflow'))
        ok_button = QPushButton("OK")
        ok_button.setDefault(True)
        ok_button.clicked.connect(dialog.accept)
        button_layout.addWidget(mlflow_button)
        button_layout.addWidget(ok_button)
        dlg_layout.addLayout(button_layout)

        clicked_mlflow = [False]
        def on_mlflow_clicked():
            clicked_mlflow[0] = True
            dialog.accept()
        mlflow_button.clicked.connect(on_mlflow_clicked)

        dialog.exec_()

        if clicked_mlflow[0]:
            self.mlflow_manager.open_ui()

    def update_location_inference_display(self):
        """位置推論表示を更新する - 上位3クラスのみ表示"""
        if not self.images:
            return
        
        current_index = self.current_index
    
        if hasattr(self, 'location_inference_checkbox') and self.location_inference_checkbox.isChecked():
            if current_index in self.location_inference_results:
                # 推論結果を取得
                result = self.location_inference_results[current_index]
                pred_class = result.get('pred_class')
                confidence = result.get('confidence', 0.0)
                all_probs = result.get('all_probs', [])
                pose_result = result.get('pose')

                # 情報テキストを構築（インライン表示）
                inference_text = f"<b>{get_text('label_location_inference_result')}</b> "

                if pred_class is not None:
                    # 一番高いクラスは背景色付きで表示
                    loc_color = get_location_color(pred_class)
                    inference_text += f"<div style='background-color: {loc_color.name()};'>"
                else:
                    # 座標・姿勢のみのモデルは背景色なし
                    inference_text += "<div>"

                # 座標・姿勢推定結果（学習時の pose ソースと同じ map 座標系 [m] / [deg]）
                if pose_result:
                    theta = pose_result.get('theta')
                    theta_text = f"{math.degrees(theta):.1f}°" if theta is not None else "-"
                    x_text = f"{pose_result['x']:.2f}"
                    y_text = f"{pose_result['y']:.2f}"
                    pose_text = get_text('label_location_pose_result', x_text, y_text, theta_text)
                    inference_text += f"<span style='font-weight: bold;'>{pose_text}</span><br>"
                    # 実測の自己位置があれば誤差も表示
                    pm = getattr(self, 'pose_manager', None)
                    if pm is not None and pm.has_any_pose():
                        cfg = getattr(self.location_model_manager, 'location_config', {}) or {}
                        gt = pm.get_pose(current_index, prefer=cfg.get('pose_source'))
                        if gt is not None:
                            pos_err = math.hypot(pose_result['x'] - gt.x, pose_result['y'] - gt.y)
                            if theta is not None:
                                d = (theta - gt.theta + math.pi) % (2 * math.pi) - math.pi
                                err_text = get_text('label_location_pose_error', f'{pos_err:.2f}', f'{abs(math.degrees(d)):.1f}')
                            else:
                                err_text = get_text('label_location_pose_error_pos_only', f'{pos_err:.2f}')
                            inference_text += f"<span style='color: #444;'>{err_text}</span><br>"

                # 格子分類の結果: Top1 セル / Top1〜N の重み付き位置と Top-N 一覧
                grid_result = result.get('grid')
                if grid_result and grid_result.get('top'):
                    from model_catalog import grid_weighted_position
                    top_n = int(getattr(self, 'location_topn', 3))
                    mode = getattr(self, 'location_grid_display', 'weighted')
                    top = grid_result['top']
                    t1 = top[0]
                    wx, wy = grid_weighted_position(top, n=top_n)
                    ex, ey = (t1['x'], t1['y']) if mode == 'top1' else (wx, wy)
                    mode_text = (get_text('opt_location_grid_top1') if mode == 'top1'
                                 else get_text('label_location_grid_weighted_n', top_n))
                    inference_text += (f"<span style='font-weight: bold;'>"
                                       f"{get_text('label_location_grid_result', mode_text, f'{ex:.2f}', f'{ey:.2f}')}"
                                       f"</span><br>")
                    inference_text += (f"<span style='color: #444;'>"
                                       f"{get_text('label_location_grid_top1', t1['ix'], t1['iy'], f'{t1['prob']:.3f}', f'{t1['x']:.2f}', f'{t1['y']:.2f}')}"
                                       f"</span><br>")
                    # 実測との誤差
                    pm = getattr(self, 'pose_manager', None)
                    if pm is not None and pm.has_any_pose():
                        cfg = getattr(self.location_model_manager, 'location_config', {}) or {}
                        gt = pm.get_pose(current_index, prefer=cfg.get('pose_source'))
                        if gt is not None:
                            e_top1 = math.hypot(t1['x'] - gt.x, t1['y'] - gt.y)
                            e_w = math.hypot(wx - gt.x, wy - gt.y)
                            inference_text += (f"<span style='color: #444;'>"
                                               f"{get_text('label_location_grid_error', f'{e_top1:.2f}', top_n, f'{e_w:.2f}')}"
                                               f"</span><br>")
                    # Top-N 一覧（確率降順）
                    for rank, it in enumerate(top[:top_n], start=1):
                        inference_text += (f"<span style='color: #555;'>"
                                           f"{get_text('label_location_grid_rank', rank, it['ix'], it['iy'], f'{it['prob']:.3f}')}"
                                           f"</span><br>")

                # 上位3クラスの予測結果を表示（すでに確率でソートされている前提）
                if pred_class is not None and all_probs:
                    # 確率が高い順にインデックスをソート
                    sorted_indices = sorted(range(len(all_probs)), key=lambda i: all_probs[i], reverse=True)
                    
                    # 上位3つ（または全部、少ない方）を取得
                    top_k = min(3, len(sorted_indices))
                    top_indices = sorted_indices[:top_k]
                    
                    inference_text += "" #"<br>上位クラス:<br>"
                    
                    for i, idx in enumerate(top_indices):
                        # すでに表示したクラスは飛ばす
                        if idx == pred_class and i > 0:
                            continue
                        
                        # 位置によって色を変える
                        if i == 0:
                            color = "white"
                        else:
                            color = get_location_color(idx).name()
                        
                        # 各クラスの予測確率
                        inference_text += f"<span style='color: {color}; font-weight: bold;'>{get_text('label_position_rank', i+1, idx, f'{all_probs[idx]:.4f}')}</span><br>"
                
                # HTMLタグを閉じる
                inference_text += "</div>"
                
                # テキストをラベルに設定（ラベルは初期化時に作成済み）
                if hasattr(self, 'location_inference_info_label'):
                    # ラベルを確実に表示
                    self.location_inference_info_label.show()
                    self.location_inference_info_label.setVisible(True)
                    
                    self.location_inference_info_label.setText(inference_text)
                    self.location_inference_info_label.setTextFormat(Qt.RichText)
                    
                    # 即座に更新を強制
                    self.location_inference_info_label.repaint()
                    self.location_inference_info_label.update()
                    
                    # 親ウィジェットと情報パネル全体も更新
                    if self.location_inference_info_label.parent():
                        self.location_inference_info_label.parent().update()
                    
                    # 情報パネル全体を更新
                    if hasattr(self, 'info_scroll'):
                        self.info_scroll.update()
                        
                    # メインウィンドウも更新
                    self.update()
                    
                    QApplication.processEvents()
                
                return True
                    
            # モデルがロードされていて推論結果がない場合は実行
            elif hasattr(self, 'location_model_manager') and self.location_model_manager.is_model_loaded():
                self.run_location_inference()
                # 再帰的に呼び出して表示を更新
                return self.update_location_inference_display()
        else:
            # 表示がオフの場合はラベルをクリア（スペースで高さを維持）
            if hasattr(self, 'location_inference_info_label'):
                self.location_inference_info_label.setText(" ")
        
        return False
    
